  smapi: ["Install the game's C# mod loader.", "Build with `dotnet build`.", "Copy the output into the game's Mods folder."],
  tmodloader: ["Place this folder in the loader's mod sources.", "Build and reload from the in-game mod menu.", "Enable the mod."],
  cet: ["Install the game's Lua script loader.", "Copy this folder into its mods directory.", "Bind the toggle key in the loader's overlay."],
  oxide: ["Install the server's plugin framework.", "Copy the `.cs` file into its plugins folder; it compiles on load.", "Grant permissions with the server console."],
  bepinex: ["Install BepInEx for the game.", "Build with `dotnet build`.", "Copy the DLL into `BepInEx/plugins`."],
  zomboid: ["Copy this folder into the game's mods directory.", "Enable it from the Mods menu.", "Adjust its sandbox options when starting a save."],
  ue4ss: ["Install UE4SS for the game.", "Copy this folder into `ue4ss/Mods`.", "Add it to `mods.txt` (or create `enabled.txt`)."],
};

function installSteps(game: Game) {
  return INSTALL[game.id] ?? INSTALL_GENERIC[game.template];
}

const INSTALL: Partial<Record<Game["id"], string[]>> = {
  minecraft: ["Install Fabric Loader 0.16+ and Fabric API for 1.21.", "Build with `./gradlew build`.", "Drop the jar from `build/libs` into `.minecraft/mods`."],
  terraria: ["Open tModLoader → Workshop → Develop Mods.", "Place this folder in `ModSources` and click **Build + Reload**.", "Enable the mod in the Mods menu."],
  palworld: ["Install UE4SS 3.x into `Pal/Binaries/Win64`.", "Copy this folder to `Pal/Binaries/Win64/ue4ss/Mods/`.", "Add the mod to `mods.txt` and restart the game."],
  rust: ["Install Oxide (uMod) or Carbon on your server.", "Copy the `.cs` file into `oxide/plugins` — it compiles on load.", "Grant permissions with `oxide.grant group default <permission>`."],
  valheim: ["Install BepInExPack Valheim (and Jötunn if listed).", "Build with `dotnet build`, or grab the DLL from `bin/`.", "Copy the DLL to `BepInEx/plugins` and launch the game."],
  zomboid: ["Copy this folder to `%UserProfile%/Zomboid/mods/`.", "Enable it in Mods (and per save under More → Mods).", "Tune it under Sandbox Options when you start a world."],
};

function readme(input: TemplateInput, files: ModFile[]) {
  const features = deriveFeatures(input);
  return code`
    # ${input.modName}

    > ${input.category.label} mod for **${input.game.name}** · ${input.game.toolchain} · v${input.version}

    ${input.prompt ? `_Prompt:_ ${input.prompt}` : ""}

    ## Features

    ${features.map((f) => `- ${f}`)}

    ## Install

    ${installSteps(input.game).map((s, i) => `${i + 1}. ${s}`)}

    ## Files

    ${files.map((f) => `- \`${f.path}\``)}

    ---
    Forged by Cyrus (${MODEL_NAME[input.model]}).`;
}

function changelog(input: TemplateInput) {
  const lines: string[] = [];
  for (let v = input.version; v >= 1; v--) {
    lines.push(`## v${v}.0.0`);
    lines.push(v === 1 ? "- Initial forge." : v === 2 ? "- Balance pass; numbers moved to config." : "- Tests, docs and polish.");
    lines.push("");
  }
  return `# Changelog\n\n${lines.join("\n")}`;
}

export function buildModFiles(input: TemplateInput): ModFile[] {
  const built =
    input.game.template === "fabric"
      ? minecraft(input)
      : input.game.template === "papyrus"
        ? skyrim(input)
        : input.game.template === "smapi"
          ? stardew(input)
          : input.game.template === "tmodloader"
            ? terraria(input)
            : input.game.template === "oxide"
              ? rustOxide(input)
              : input.game.template === "bepinex"
                ? valheimBepInEx(input)
                : input.game.template === "zomboid"
                  ? zomboidLua(input)
                  : input.game.template === "ue4ss"
                    ? palworldUE4SS(input)
                    : cyberpunk(input);

  const out: ModFile[] = [...built.files];
  if (input.model === "katara") return out.slice(0, 3);

  if (built.config) out.push(built.config);
  if (built.l10n) out.push(built.l10n);
  if (input.model === "yakko") out.push(built.test);
  out.push(file("README.md", readme(input, out)));
  if (input.model === "yakko" || input.version > 1) out.push(file("CHANGELOG.md", changelog(input)));
  return out;
}

export function buildModNotes(input: TemplateInput): string {
  const n = numbers(input);
  const features = deriveFeatures(input);
  const fxs = effectsFor(input);
  return code`
    # ${input.modName}

    A ${input.category.label.toLowerCase()} mod for ${input.game.name}, built on ${input.game.toolchain}. ${input.category.description}

    ## What it does

    ${features.map((f) => `- ${f}`)}

    ## Install

    ${installSteps(input.game).map((s, i) => `${i + 1}. ${s}`)}

    ## Tuning

    - **Power** \`${n.power}\` — raise for late-game saves, lower for vanilla feel.
    - **Cooldown** \`${n.cooldown}s\` — under 2s gets spammy in multiplayer.
    - **Radius** \`${n.radius}\` — affects ${fxs[0].label.toLowerCase()}.

    ## Known limitations

    - Visual assets are placeholders; drop real textures/models into the asset folder.
    - ${input.game.template === "papyrus" ? "Script properties must be filled in the editor kit before the scripts do anything." : input.game.template === "cet" ? "Record IDs assume vanilla game data; other overhauls may conflict." : "Not tested against other mods that touch the same hooks."}

    ## Next ideas

    - Ask Cyrus for a v${input.version + 1} that adds a crafting recipe or a config menu.
    - Try **Yakko** for tests and a full changelog.`;
}
