import type { CategoryKey, ModFile } from "@/lib/cyrus/types";
import {
  ARCH,
  code,
  deriveFeatures,
  effectsFor,
  file,
  identity,
  MODEL_NAME,
  numbers,
  sub,
  type Built,
  type Effect,
  type EffectKey,
  type TemplateInput,
} from "../kit";

/* ═════════════ Valheim · BepInEx 5 · HarmonyX · C# (Jötunn where it pulls its weight) ═════════════ */

type Dmg = "m_frost" | "m_fire" | "m_lightning" | "m_poison" | "m_spirit";

/** Valheim code per effect. TARGET is the Character being hit, SOURCE the attacker, POWER a float expression. */
interface VFx {
  /** HitData.DamageTypes field the effect adds. */
  dmg?: Dmg;
  /** Vanilla crafting material its recipes ask for. */
  mat: string;
  hit?: string;
  /** Runs once per proc on SOURCE. */
  self?: string;
  /** `self` only compiles when SOURCE is a Player. */
  player?: boolean;
}

const addSE = (name: string, on = "TARGET") => `${on}.GetSEMan().AddStatusEffect("${name}".GetStableHashCode(), resetTime: true)`;

const VFX: Record<EffectKey, VFx> = {
  frost: { dmg: "m_frost", mat: "FreezeGland", hit: `TARGET.GetSEMan().AddStatusEffect(ObjectDB.instance.GetStatusEffect("Frost".GetStableHashCode()), resetTime: true);` },
  fire: { dmg: "m_fire", mat: "SurtlingCore", hit: `(${addSE("Burning")} as SE_Burning)?.AddFireDamage(POWER);` },
  storm: { dmg: "m_lightning", mat: "Thunderstone", hit: `Object.Instantiate(ZNetScene.instance.GetPrefab("lightningAOE"), TARGET.transform.position, Quaternion.identity);` },
  blink: { mat: "GreydwarfEye", player: true, self: `SOURCE.TeleportTo(SOURCE.transform.position + SOURCE.transform.forward * RADIUS, SOURCE.transform.rotation, distantTeleport: false);` },
  heal: { mat: "Bloodbag", self: `SOURCE.Heal(POWER * 0.5f, showText: true);` },
  poison: { dmg: "m_poison", mat: "Guck", hit: `(${addSE("Poison")} as SE_Poison)?.AddDamage(POWER);` },
  summon: { mat: "BoneFragments", self: `Object.Instantiate(ZNetScene.instance.GetPrefab("Skeleton_Friendly"), SOURCE.transform.position + SOURCE.transform.right * 2f, SOURCE.transform.rotation);` },
  flight: { mat: "Feathers", self: `${addSE("SlowFall", "SOURCE")}; // the feather cape's effect` },
  void: { mat: "Ectoplasm", hit: `${addSE("Smoked")};\n${addSE("Wet")};` },
  lunar: {
    mat: "Crystal",
    hit: `if (EnvMan.instance.IsNight())\n{\n    var moonlight = new HitData { m_point = TARGET.GetCenterPoint() };\n    moonlight.m_damage.m_spirit = POWER * 0.5f;\n    moonlight.SetAttacker(SOURCE);\n    TARGET.Damage(moonlight);\n}`,
  },
  // auto also ships its own Smelter / Fermenter patch (see productionPatch).
  auto: { mat: "Bronze", player: true, self: `SOURCE.m_autoPickupRange = Mathf.Max(SOURCE.m_autoPickupRange, RADIUS); // vanilla is 2 m` },
  neon: { mat: "Crystal", player: true, self: `SOURCE.Message(MessageHud.MessageType.TopLeft, "<color=#ff4fd8>LABEL</color>");` },
};

const DMG_TYPE: Record<Dmg, string> = { m_frost: "Frost", m_fire: "Fire", m_lightning: "Lightning", m_poison: "Poison", m_spirit: "Spirit" };

/** Biome keywords → Heightmap.Biome, a vanilla location to clone, its treasure chest and vegetation worth thickening. */
const BIOMES: [RegExp, string, string, string, string[]][] = [
  [/mountain|snow|frost|ice|icy|glacier|peak|blizzard|cold/, "Mountain", "DrakeNest01", "TreasureChest_mountains", ["FirTree", "MineRock_Obsidian"]],
  [/swamp|bog|marsh|toxic|poison|plague|rot/, "Swamp", "SunkenCrypt4", "TreasureChest_swamp", ["SwampTree1"]],
  [/plains|desert|savanna|fire|ember|lava|ash|sun/, "Plains", "GoblinCamp2", "TreasureChest_plains_stone", ["Birch1", "Pickable_Barley_Wild", "Pickable_Flax_Wild"]],
  [/forest|wood|grove|dark|shadow|void|troll/, "BlackForest", "Crypt2", "TreasureChest_blackforest", ["FirTree", "Pinetree_01", "MineRock_Tin"]],
  [/./, "Meadows", "WoodHouse1", "TreasureChest_meadows", ["Beech1", "Oak1"]],
];

interface Ctx {
  input: TemplateInput;
  k: CategoryKey;
  cls: string;
  snake: string;
  n: ReturnType<typeof numbers>;
  fx: Effect[];
  /** Plugin and balance class names. */
  P: string;
  B: string;
  text: string;
}

/* ───────────── config entries: one list drives the C# binds and the .cfg BepInEx writes ───────────── */

type SType = "bool" | "float" | "int" | "key";
interface Setting {
  section: string;
  key: string;
  type: SType;
  def: number | boolean | string;
  desc: string;
  range?: [number, number];
}
const fl = (section: string, key: string, def: number, desc: string, range: [number, number]): Setting => ({ section, key, type: "float", def, desc, range });
const nt = (section: string, key: string, def: number, desc: string, range: [number, number]): Setting => ({ section, key, type: "int", def: Math.round(def), desc, range });
const bl = (section: string, key: string, def: boolean, desc: string): Setting => ({ section, key, type: "bool", def, desc });
const hk = (section: string, key: string, def: string, desc: string): Setting => ({ section, key, type: "key", def, desc });

const CS_TYPE: Record<SType, string> = { bool: "bool", float: "float", int: "int", key: "KeyboardShortcut" };
const CFG_TYPE: Record<SType, string> = { bool: "Boolean", float: "Single", int: "Int32", key: "KeyboardShortcut" };
const lit = (s: Setting, v = s.def) => (s.type === "float" ? `${v}f` : s.type === "key" ? `new KeyboardShortcut(KeyCode.${v})` : String(v));

function bindLine(s: Setting) {
  const t = CS_TYPE[s.type];
  const desc = s.range ? `new ConfigDescription("${s.desc}", new AcceptableValueRange<${t}>(${lit(s, s.range[0])}, ${lit(s, s.range[1])}))` : `"${s.desc}"`;
  return `${s.key} = Config.Bind("${s.section}", "${s.key}", ${lit(s)}, ${desc});`;
}

function cfgFile(c: Ctx, settings: Setting[]) {
  const out = [`## Settings file was created by plugin ${c.input.modName} v${c.input.version}.0.0`, `## Plugin GUID: com.cyrus.${c.snake}`, ""];
  for (const section of [...new Set(settings.map((s) => s.section))].sort()) {
    out.push(`[${section}]`, "");
    for (const s of settings.filter((x) => x.section === section).sort((a, b) => a.key.localeCompare(b.key))) {
      out.push(`## ${s.desc}`, `# Setting type: ${CFG_TYPE[s.type]}`, `# Default value: ${s.def}`);
      if (s.range) out.push(`# Acceptable value range: From ${s.range[0]} to ${s.range[1]}`);
      out.push(`${s.key} = ${s.def}`, "");
    }
  }
  return out.join("\n");
}

/** What each archetype contributes to the project. */
interface ArchOut {
  settings: Setting[];
  /** Second file: the patch that makes the mod work. */
  main: ModFile;
  extra: ModFile[];
  words: Record<string, string>;
  /** Members of the pure, unit-tested balance class. */
  balance: string;
  tests: string;
  prefab?: string;
  jotunn?: boolean;
  awake?: string;
  usings?: string[];
  /** Extra managed assemblies from valheim_Data/Managed. */
  refs?: string[];
}

/* ───────────── effect snippet helpers ───────────── */

const has = (c: Ctx, key: EffectKey) => c.fx.some((e) => e.key === key);
const fill = (c: Ctx, s: string, target: string, source: string, power: string) =>
  sub(s, target, source, { POWER: power, RADIUS: `${c.n.radius}f`, LABEL: c.input.modName });
const dmgsOf = (c: Ctx) => [...new Set(c.fx.map((e) => VFX[e.key].dmg).filter((d): d is Dmg => !!d))];
const hits = (c: Ctx, target: string, source: string, power: string) =>
  c.fx.flatMap((e) => (VFX[e.key].hit ? [fill(c, VFX[e.key].hit!, target, source, power)] : []));
const selfs = (c: Ctx, source: string, power: string, isPlayer: boolean, skip: EffectKey[] = []) =>
  c.fx.flatMap((e) => {
    const v = VFX[e.key];
    return v.self && (isPlayer || !v.player) && !skip.includes(e.key) ? [fill(c, v.self, "", source, power)] : [];
  });

/** A HitData carrying the effects' elemental damage (blunt when none apply). */
function strike(c: Ctx, target: string, source: string, power: string) {
  const d = dmgsOf(c);
  return code`
    var strike = new HitData { m_point = ${target}.GetCenterPoint() };
    ${(d.length ? d : ["m_blunt"]).map((x) => `strike.m_damage.${x} = ${power};`)}
    strike.SetAttacker(${source});
    ${target}.Damage(strike);`;
}

/** Pulses the effects from `src` (a Player): per-enemy hits around it, then its own buffs. */
function castBlock(c: Ctx, src: string, power: string, radius: string, passive = false) {
  // Passive pulses never move the player or spawn allies; those wait for the hotkey.
  const self = selfs(c, src, power, true, passive ? ["blink", "summon", "neon"] : []);
  const perTarget = hits(c, "target", src, power);
  if (dmgsOf(c).length || (!passive && !perTarget.length && !self.length)) perTarget.unshift(strike(c, "target", src, power));
  const loop = code`
    var targets = new List<Character>();
    Character.GetCharactersInRange(${src}.transform.position, ${radius}, targets);
    foreach (var target in targets)
    {
        if (target == ${src} || target.IsDead() || !BaseAI.IsEnemy(${src}, target)) continue;
        ${perTarget}
    }`;
  return code`
    ${perTarget.length ? loop : ""}
    ${self}`;
}

/** In-game name: drops filler like "Item" or "Tameable"; entities get a singular noun. */
function displayName(c: Ctx, singular = false) {
  const all = c.input.modName.split(/\s+/);
  const words = all.filter((w) => !/^(items?|creatures?|vehicles?|mechanics?|tameable|rideable|mod)$/i.test(w));
  const out = words.length ? words : all;
  if (singular) out[out.length - 1] = out[out.length - 1].replace(/ves$/i, "f").replace(/([^s])s$/i, "$1");
  return out.join(" ");
}

/** On-hit body for a Character.Damage postfix, re-entrancy guarded because effects can deal damage themselves. */
function onHit(c: Ctx, target: string, source: string, power: string, isPlayer: boolean) {
  let body = [...hits(c, target, source, power), ...selfs(c, source, power, isPlayer)];
  if (!body.length) body = [strike(c, target, source, power)];
  return code`
    _applying = true;
    try
    {
        ${body}
    }
    finally
    {
        _applying = false;
    }`;
}

/* ───────────── entry point ───────────── */

export function valheimBepInEx(input: TemplateInput): Built {
  const { cls, snake } = identity(input.modName);
  const text = `${input.prompt} ${input.modName}`.toLowerCase();
  // Routing keys off words like "storm"; a prompt that is plainly about a ship, or about taming/riding a creature,
  // still gets entity code.
  const loose = !["entity", "world"].includes(ARCH[input.category.key]);
  const k: CategoryKey =
    loose && /\b(ship|boat|longship|karve|raft|drakkar)s?\b/.test(text)
      ? "vehicles"
      : loose && /\b(tam(e|ed|eable|ing)|rid(e|eable|ing)|saddled?)\b/.test(text) && CREATURES.some(([re]) => re.test(text))
        ? "creatures"
        : input.category.key;
  const c: Ctx = {
    input,
    k,
    cls,
    snake,
    n: numbers(input),
    fx: effectsFor(input),
    P: `${cls}Plugin`,
    B: `${cls}Balance`,
    text,
  };
  const arch = ARCH[k];
  const spell = k === "magic" || (k === "weapons" && /\b(staff|wand|scepter|sceptre)\b/.test(text));
  const a =
    arch === "item" ? (spell ? magicArch(c) : itemArch(c)) : arch === "entity" ? entityArch(c) : arch === "world" ? worldArch(c) : arch === "system" ? systemArch(c) : visualArch(c);

  const settings = [bl("General", "Enabled", true, "Master switch for everything this mod adds."), ...a.settings];
  if (has(c, "auto")) {
    settings.push(fl("Production", "ProductionSpeed", Number((1 + c.n.intensity).toFixed(2)), "Speed multiplier for smelters, kilns, fermenters and cooking stations.", [1, 10]));
    if (a.main.path !== "src/Patches/ProductionPatch.cs") a.extra.push(productionPatch(c));
    const join = (...parts: string[]) => parts.filter(Boolean).map((p) => p.trimEnd()).join("\n\n");
    a.balance = join(
      a.balance,
      code`
        /// <summary>Production time after the speed multiplier; never slower than vanilla.</summary>
        public static float ProductionSeconds(float seconds, float speed) => seconds / Clamp(speed, 1f, 10f);`,
    );
    a.tests = join(
      a.tests,
      code`
        [Theory]
        [InlineData(30f, 2f, 15f)]

        [InlineData(30f, 2f, 15f)]
        [InlineData(30f, 0.2f, 30f)]
        public void ProductionIsNeverSlowerThanVanilla(float seconds, float speed, float expected) =>
            Assert.Equal(expected, ${c.B}.ProductionSeconds(seconds, speed));`,
    );
  }

  const files = [pluginFile(c, a, settings), a.main, csproj(c, a), ...a.extra, manifest(c, a)];
  return { files, config: file(`config/com.cyrus.${snake}.cfg`, cfgFile(c, settings)), l10n: l10nFile(c, a), test: testFile(c, a) };
}

function pluginFile(c: Ctx, a: ArchOut, settings: Setting[]): ModFile {
  const { input, cls, P, B } = c;
  const vNote = input.version > 1 ? `// v${input.version}: retuned the numbers and moved every one of them into the BepInEx config.` : "";
  return file(
    `src/${P}.cs`,
    code`
      ${a.usings ?? ""}
      using BepInEx;
      using BepInEx.Configuration;
      using BepInEx.Logging;
      using HarmonyLib;
      ${a.jotunn ? ["using Jotunn.Managers;", "using Jotunn.Utils;"] : ""}
      using UnityEngine;

      namespace ${cls}
      {
          /// <summary>${input.modName}: ${input.category.label.toLowerCase()} for Valheim. Forged by Cyrus (${MODEL_NAME[input.model]}) v${input.version}.</summary>
          ${vNote}
          [BepInPlugin(PluginGUID, PluginName, PluginVersion)]
          ${a.jotunn ? ["[BepInDependency(Jotunn.Main.ModGuid)]", "[NetworkCompatibility(CompatibilityLevel.EveryoneMustHaveMod, VersionStrictness.Minor)]"] : ""}
          public class ${P} : BaseUnityPlugin
          {
              public const string PluginGUID = "com.cyrus.${c.snake}";
              public const string PluginName = "${input.modName}";
              public const string PluginVersion = "${input.version}.0.0";
              ${a.prefab ? `public const string PrefabName = "${a.prefab}";` : ""}

              internal static ManualLogSource Log;

              ${settings.map((s) => `public static ConfigEntry<${CS_TYPE[s.type]}> ${s.key};`)}

              private Harmony _harmony;

              private void Awake()
              {
                  Log = Logger;
                  BindConfig();

                  _harmony = new Harmony(PluginGUID);
                  _harmony.PatchAll();
                  ${a.awake ?? ""}

                  Logger.LogInfo($"{PluginName} v{PluginVersion} loaded");
              }

              private void BindConfig()
              {
                  ${settings.map(bindLine)}
              }

              private void OnDestroy() => _harmony?.UnpatchSelf();
          }

          /// <summary>Pure balance math with no Unity types, so it can be unit tested outside the game.</summary>
          public static class ${B}
          {
              ${a.balance}

              public static float Clamp(float value, float min, float max) => value < min ? min : value > max ? max : value;

              public static int Clamp(int value, int min, int max) => value < min ? min : value > max ? max : value;
          }
      }`,
  );
}

function csproj(c: Ctx, a: ArchOut): ModFile {
  const ref = (name: string, dir = "$(ManagedPath)", extra = "") => `<Reference Include="${name}" HintPath="${dir}\\${name}.dll" Private="false"${extra} />`;
  const managed = ["assembly_utils", "UnityEngine", "UnityEngine.CoreModule", ...(a.refs ?? [])];
  return file(
    `${c.cls}.csproj`,
    code`
      <Project Sdk="Microsoft.NET.Sdk">

        <PropertyGroup>
          <TargetFramework>net48</TargetFramework>
          <AssemblyName>${c.cls}</AssemblyName>
          <RootNamespace>${c.cls}</RootNamespace>
          <Version>${c.input.version}.0.0</Version>
          <LangVersion>latest</LangVersion>
          <AllowUnsafeBlocks>true</AllowUnsafeBlocks>
          <VALHEIM_INSTALL Condition="'$(VALHEIM_INSTALL)' == ''">C:\\Program Files (x86)\\Steam\\steamapps\\common\\Valheim</VALHEIM_INSTALL>
          <BepInExPath>$(VALHEIM_INSTALL)\\BepInEx</BepInExPath>
          <ManagedPath>$(VALHEIM_INSTALL)\\valheim_Data\\Managed</ManagedPath>
        </PropertyGroup>

        <ItemGroup>
          <Compile Remove="tests\\**" />
          ${a.jotunn ? `<Translations Include="Translations\\**\\*.json" />` : ""}
        </ItemGroup>

        <ItemGroup>
          <!-- Publicized assembly_valheim: private members like ZNetScene.m_namedPrefabs and Player.Update are reachable. -->
          <PackageReference Include="BepInEx.AssemblyPublicizer.MSBuild" Version="0.4.2" PrivateAssets="all" />
          ${a.jotunn ? `<PackageReference Include="JotunnLib" Version="2.20.1" />` : ""}
        </ItemGroup>

        <ItemGroup>
          ${ref("BepInEx", "$(BepInExPath)\\core")}
          ${ref("0Harmony", "$(BepInExPath)\\core")}
          ${ref("assembly_valheim", "$(ManagedPath)", ` Publicize="true"`)}
          ${managed.map((m) => ref(m))}
        </ItemGroup>

        <Target Name="DeployToBepInEx" AfterTargets="Build" Condition="Exists('$(BepInExPath)\\plugins')">
          <Copy SourceFiles="$(TargetPath)" DestinationFolder="$(BepInExPath)\\plugins\\$(AssemblyName)" />
          ${a.jotunn ? `<Copy SourceFiles="@(Translations)" DestinationFolder="$(BepInExPath)\\plugins\\$(AssemblyName)\\Translations\\%(RecursiveDir)" />` : ""}
        </Target>

      </Project>`,
  );
}

function manifest(c: Ctx, a: ArchOut): ModFile {
  const deps = ["denikson-BepInExPack_Valheim-5.4.2202", ...(a.jotunn ? ["ValheimModding-Jotunn-2.20.1"] : [])];
  return file(
    "manifest.json",
    JSON.stringify({ name: c.cls, version_number: `${c.input.version}.0.0`, website_url: "", description: deriveFeatures(c.input)[0].slice(0, 250), dependencies: deps }, null, 2) + "\n",
  );
}

function l10nFile(c: Ctx, a: ArchOut): ModFile {
  if (a.jotunn) return file(`Translations/English/${c.snake}.json`, JSON.stringify(a.words, null, 2) + "\n");
  return file(
    "src/Patches/LocalizationPatch.cs",
    code`
      using System.Collections.Generic;
      using HarmonyLib;

      namespace ${c.cls}.Patches
      {
          /// <summary>Adds the mod's $tokens whenever Valheim (re)loads a language. Other languages fall back to English.</summary>
          [HarmonyPatch(typeof(Localization), nameof(Localization.SetupLanguage))]
          public static class LocalizationPatch
          {
              private static readonly Dictionary<string, string> English = new Dictionary<string, string>
              {
                  ${Object.entries(a.words).map(([key, text]) => `{ "${key}", "${text}" },`)}
              };

              private static void Postfix(Localization __instance)
              {
                  foreach (var pair in English) __instance.AddWord(pair.Key, pair.Value);
              }
          }
      }`,
  );
}

function testFile(c: Ctx, a: ArchOut): ModFile {
  return file(
    `tests/${c.cls}.Tests/${c.B}Tests.cs`,
    code`
      using Xunit;

      namespace ${c.cls}.Tests
      {
          public class ${c.B}Tests
          {
              ${a.tests}

              [Theory]
              [InlineData(-5f, 0f)]
              [InlineData(0.35f, 0.35f)]
              [InlineData(9f, 1f)]
              public void ClampKeepsConfigValuesInRange(float raw, float expected) =>
                  Assert.Equal(expected, ${c.B}.Clamp(raw, 0f, 1f));
          }
      }`,
  );
}

/** Speeds up every production building; the `auto` effect's patch. */
function productionPatch(c: Ctx): ModFile {
  const { cls, P, B } = c;
  const speed = `${P}.ProductionSpeed.Value`;
  return file(
    "src/Patches/ProductionPatch.cs",
    code`
      using HarmonyLib;
      using UnityEngine;

      namespace ${cls}.Patches
      {
          /// <summary>Each building keeps its own copy of these fields, so scaling them in Awake is per-instance and safe.</summary>
          [HarmonyPatch]
          public static class ProductionPatch
          {
              // Smelter covers the smelter, blast furnace, charcoal kiln, spinning wheel and windmill.
              [HarmonyPatch(typeof(Smelter), nameof(Smelter.Awake)), HarmonyPostfix]
              private static void SmelterAwake(Smelter __instance)
              {
                  if (!${P}.Enabled.Value) return;
                  __instance.m_secPerProduct = ${B}.ProductionSeconds(__instance.m_secPerProduct, ${speed});
                  __instance.m_maxOre = Mathf.RoundToInt(__instance.m_maxOre * Mathf.Sqrt(${speed}));
              }

              [HarmonyPatch(typeof(Fermenter), nameof(Fermenter.Awake)), HarmonyPostfix]
              private static void FermenterAwake(Fermenter __instance)
              {
                  if (${P}.Enabled.Value) __instance.m_fermentationDuration = ${B}.ProductionSeconds(__instance.m_fermentationDuration, ${speed});
              }

              [HarmonyPatch(typeof(CookingStation), nameof(CookingStation.Awake)), HarmonyPostfix]
              private static void CookingStationAwake(CookingStation __instance)
              {
                  if (!${P}.Enabled.Value) return;
                  foreach (var conversion in __instance.m_conversion)
                      conversion.m_cookTime = ${B}.ProductionSeconds(conversion.m_cookTime, ${speed});
              }
          }
      }`,
  );
}

/** Automation mechanic: tops up smelters and kilns from nearby chests. */
function feederPatch(c: Ctx): ModFile {
  const { cls, P } = c;
  return file(
    "src/Patches/SmelterFeederPatch.cs",
    code`
      using HarmonyLib;
      using UnityEngine;

      namespace ${cls}.Patches
      {
          /// <summary>
          /// UpdateSmelter ticks once a second on the ZDO owner. Pulls fuel and ore from unlocked chests in range
          /// through the same RPCs the player's "add ore" interaction uses, so every client stays in sync.
          /// </summary>
          [HarmonyPatch(typeof(Smelter), nameof(Smelter.UpdateSmelter))]
          public static class SmelterFeederPatch
          {
              private static readonly Collider[] Hits = new Collider[64];

              private static void Postfix(Smelter __instance)
              {
                  if (!${P}.Enabled.Value || !__instance.m_nview.IsValid() || !__instance.m_nview.IsOwner()) return;
                  int count = Physics.OverlapSphereNonAlloc(__instance.transform.position, ${P}.FeedRadius.Value, Hits, LayerMask.GetMask("piece", "piece_nonsolid"));

                  for (int i = 0; i < count; i++)
                  {
                      var container = Hits[i].GetComponentInParent<Container>();
                      if (!container || container.IsInUse() || !container.m_nview.IsOwner()) continue;
                      var inventory = container.GetInventory();

                      if (__instance.m_fuelItem && __instance.GetFuel() < __instance.m_maxFuel - 1)
                      {
                          var fuel = __instance.m_fuelItem.m_itemData.m_shared.m_name;
                          if (inventory.HaveItem(fuel))
                          {
                              inventory.RemoveItem(fuel, 1);
                              __instance.m_nview.InvokeRPC("RPC_AddFuel");
                          }
                      }

                      if (__instance.GetQueueSize() >= __instance.m_maxOre) continue;
                      foreach (var conversion in __instance.m_conversion)
                      {
                          var ore = conversion.m_from.m_itemData.m_shared.m_name;
                          if (!inventory.HaveItem(ore)) continue;
                          inventory.RemoveItem(ore, 1);
                          __instance.m_nview.InvokeRPC("RPC_AddOre", conversion.m_from.gameObject.name);
                          break;
                      }
                  }
              }
          }
      }`,
  );
}

/* ───────────── item: weapons, items (vanilla ObjectDB) and magic (Jötunn) ───────────── */

const WEAPONS: [RegExp, string][] = [
  [/battle ?axe|great ?axe/, "Battleaxe"],
  [/axe/, "AxeIron"],
  [/great ?sword|claymore/, "THSwordKrom"],
  [/mace|hammer|club|maul/, "MaceIron"],
  [/spear|javelin/, "SpearElderbark"],
  [/atgeir|glaive|halberd|polearm/, "AtgeirIron"],
  [/crossbow|arbalest/, "CrossbowArbalest"],
  [/bow/, "BowFineWood"],
  [/knife|dagger/, "KnifeSilver"],
];
const STAFFS: Partial<Record<EffectKey, string>> = { frost: "StaffIceShards", storm: "StaffLightning", summon: "StaffSkeleton", heal: "StaffShield" };

const itemBalance = code`
  /// <summary>Share of the base elemental damage added per upgrade (Valheim's m_damagesPerLevel).</summary>
  public const float PerLevelRatio = 0.25f;

  /// <summary>Mirrors ItemDrop.ItemData.GetDamage: base + perLevel * (quality - 1), capped at four upgrades.</summary>
  public static float DamageAtQuality(float baseDamage, int quality) => baseDamage + baseDamage * PerLevelRatio * (Clamp(quality, 1, 4) - 1);

  public static bool Procs(float chance, float roll) => roll < Clamp(chance, 0f, 1f);`;

function itemTests(c: Ctx, dmg: number) {
  const at = (q: number) => Number((dmg * (1 + 0.25 * (q - 1))).toFixed(2));
  return code`
    [Theory]
    [InlineData(1, ${at(1)}f)]
    [InlineData(3, ${at(3)}f)]
    [InlineData(4, ${at(4)}f)]
    public void ElementalDamageScalesPerUpgrade(int quality, float expected) =>
        Assert.Equal(expected, ${c.B}.DamageAtQuality(${dmg}f, quality), 2);

    [Fact]
    public void QualityIsCappedAtFour() =>
        Assert.Equal(${c.B}.DamageAtQuality(${dmg}f, 4), ${c.B}.DamageAtQuality(${dmg}f, 9));

    [Fact]
    public void ProcChanceIsClampedToCertainty()
    {
        Assert.True(${c.B}.Procs(5f, 0.999f));
        Assert.False(${c.B}.Procs(-1f, 0f));
    }`;
}

/** Character.Damage postfix firing the effects when the local player hits with this mod's item. */
function weaponHitPatch(c: Ctx): ModFile {
  const { cls, P, B } = c;
  return file(
    `src/Patches/${cls}HitPatch.cs`,
    code`
      using HarmonyLib;
      using UnityEngine;
      using Object = UnityEngine.Object;

      namespace ${cls}.Patches
      {
          /// <summary>Character.Damage runs on the attacker's client, so the effects fire where the swing happened.</summary>
          [HarmonyPatch(typeof(Character), nameof(Character.Damage))]
          public static class ${cls}HitPatch
          {
              private static bool _applying;

              private static void Postfix(Character __instance, HitData hit)
              {
                  if (_applying || !${P}.Enabled.Value || hit == null || __instance.IsDead()) return;
                  if (!(hit.GetAttacker() is Player player) || player != Player.m_localPlayer) return;

                  if (!(hit.GetAttacker() is Player player) || player != Player.m_localPlayer) return;

                  var weapon = player.GetCurrentWeapon();
                  if (weapon?.m_dropPrefab == null || weapon.m_dropPrefab.name != ${P}.PrefabName) return;
                  if (!${B}.Procs(${P}.ProcChance.Value, Random.value)) return;

                  ${onHit(c, "__instance", "player", `${P}.Power.Value`, true)}
              }
          }
      }`,
  );
}

/** Hotkey ability while the item is equipped (non-weapon items). */
function abilityPatch(c: Ctx): ModFile {
  const { cls, P } = c;
  return file(
    `src/Patches/${cls}AbilityPatch.cs`,
    code`
      using System.Collections.Generic;
      using HarmonyLib;
      using UnityEngine;
      using Object = UnityEngine.Object;

      namespace ${cls}.Patches
      {
          [HarmonyPatch(typeof(Player), nameof(Player.Update))]
          public static class ${cls}AbilityPatch
          {
              private static float _cooldown;

              private static void Postfix(Player __instance)
              {
                  if (__instance != Player.m_localPlayer || !${P}.Enabled.Value) return;
                  if (_cooldown > 0f)
                  {
                      _cooldown -= Time.deltaTime;
                      return;
                  }
                  if (!__instance.TakeInput() || !${P}.AbilityKey.Value.IsDown()) return;

                  var equipped = __instance.GetInventory().GetEquippedItems().Find(i => i.m_dropPrefab && i.m_dropPrefab.name == ${P}.PrefabName);
                  if (equipped == null) return;

                  ${castBlock(c, "__instance", `${P}.Power.Value`, `${P}.Radius.Value`)}
                  _cooldown = ${P}.AbilityCooldown.Value;
              }
          }
      }`,
  );
}

function itemArch(c: Ctx): ArchOut {
  const { cls, snake, P, B, n, k, input } = c;
  const kind =
    k === "weapons" ? "weapon" : /food|potion|mead|drink|stew|soup|elixir|tonic|brew/.test(c.text) ? "consumable" : /pickaxe|pick|tool|mining|drill/.test(c.text) ? "tool" : "trinket";
  const base =
    kind === "weapon" ? (WEAPONS.find(([re]) => re.test(c.text))?.[1] ?? "SwordIron") : kind === "consumable" ? "MeadHealthMinor" : kind === "tool" ? "PickaxeIron" : "BeltStrength";
  const recipeFrom = kind === "consumable" ? "MeadBaseHealthMinor" : base;
  const dmgs = dmgsOf(c).length ? dmgsOf(c) : (["m_spirit"] as Dmg[]);
  const elemental = Number((n.power * 4).toFixed(1));
  const mats = [...new Set(c.fx.map((e) => VFX[e.key].mat))];
  const reqs: [string, number, number][] =
    kind === "consumable"
      ? [["Honey", 10, 0], ["Blueberries", 5, 0], ...mats.map((m): [string, number, number] => [m, 2, 0])]
      : [[kind === "trinket" ? "Silver" : "Iron", 20, 10], [kind === "trinket" ? "LeatherScraps" : "ElderBark", 6, 2], ...mats.map((m, i): [string, number, number] => [m, i ? 4 : 8, i ? 2 : 4])];
  const status = kind !== "weapon";

  const settings: Setting[] =
    kind === "weapon"
      ? [
          fl("Item", "ElementalDamage", elemental, "Elemental damage added on top of the base weapon.", [0, 300]),
          fl("Item", "AttackForce", Math.round(40 + n.power * 2), "Knockback applied on hit.", [0, 200]),
          fl("Effects", "ProcChance", n.chance, "Chance for on-hit effects to trigger.", [0, 1]),
          fl("Effects", "Power", n.power, "Strength of the on-hit effects.", [1, 50]),
        ]
      : [
          kind === "consumable"
            ? fl("Item", "DurationSeconds", n.duration * 60, "How long the effect lasts.", [30, 3600])
            : nt("Item", "CarryWeight", n.interval * 15, "Extra carry weight while equipped.", [0, 300]),
          fl("Item", "RegenMultiplier", Number((1 + n.power / 20).toFixed(2)), "Health regeneration multiplier.", [1, 3]),
          ...(kind === "tool" ? [fl("Item", "MiningDamage", Math.round(n.power * 8), "Pickaxe damage against rock and ore.", [1, 300])] : []),
          ...(kind === "consumable"
            ? []
            : [
                hk("Hotkeys", "AbilityKey", "G", "Activates the equipped item's ability."),
                fl("Ability", "AbilityCooldown", n.cooldown, "Seconds between ability uses.", [0.5, 120]),
                fl("Ability", "Radius", n.radius, "Ability radius in meters.", [1, 30]),
                fl("Effects", "Power", n.power, "Strength of the ability's effects.", [1, 50]),
              ]),
        ];

  const configure =
    kind === "weapon"
      ? [
          ...dmgs.flatMap((d) => [`shared.m_damages.${d} = ${P}.ElementalDamage.Value;`, `shared.m_damagesPerLevel.${d} = ${P}.ElementalDamage.Value * ${B}.PerLevelRatio;`]),
          `shared.m_attackForce = ${P}.AttackForce.Value;`,
        ]
      : kind === "consumable"
        ? [`shared.m_consumeStatusEffect = CreateStatus(db, shared);`]
        : [
            kind === "tool" ? `shared.m_damages.m_pickaxe = ${P}.MiningDamage.Value;\nshared.m_toolTier += 1;` : "",
            `shared.m_equipStatusEffect = CreateStatus(db, shared);`,
          ];

  const main = file(
    "src/Patches/ItemRegistration.cs",
    code`
      using HarmonyLib;
      using UnityEngine;
      using Object = UnityEngine.Object;

      namespace ${cls}.Patches
      {
          /// <summary>Clones ${base} into ${cls}, registers it with ObjectDB (item + recipe) and ZNetScene (network prefab).</summary>
          [HarmonyPatch]
          public static class ItemRegistration
          {
              private const string BasePrefab = "${base}";
              ${status ? `private const string StatusName = "SE_${cls}";` : ""}
              private static GameObject _prefab;
              private static GameObject _container;

              [HarmonyPatch(typeof(ObjectDB), nameof(ObjectDB.Awake)), HarmonyPostfix]
              private static void ObjectDBAwake(ObjectDB __instance) => Register(__instance);

              [HarmonyPatch(typeof(ObjectDB), nameof(ObjectDB.CopyOtherDB)), HarmonyPostfix]
              private static void ObjectDBCopyOtherDB(ObjectDB __instance) => Register(__instance);

              [HarmonyPatch(typeof(ZNetScene), nameof(ZNetScene.Awake)), HarmonyPostfix]
              private static void ZNetSceneAwake(ZNetScene __instance)
              {
                  var prefab = GetOrCreate(__instance.GetPrefab(BasePrefab));
                  if (!prefab || __instance.m_namedPrefabs.ContainsKey(prefab.name.GetStableHashCode())) return;
                  __instance.m_prefabs.Add(prefab);
                  __instance.m_namedPrefabs.Add(prefab.name.GetStableHashCode(), prefab);
              }

              private static void Register(ObjectDB db)
              {
                  // The main-menu ObjectDB starts empty; wait for the populated one.
                  if (db.m_items.Count == 0 || !db.GetItemPrefab("Amber")) return;
                  var prefab = GetOrCreate(db.GetItemPrefab(BasePrefab));
                  if (!prefab) return;

                  var shared = prefab.GetComponent<ItemDrop>().m_itemData.m_shared;
                  shared.m_name = "$item_${snake}";
                  shared.m_description = "$item_${snake}_description";
                  ${configure}

                  if (db.GetItemPrefab(prefab.name)) return;
                  db.m_items.Add(prefab);
                  db.m_itemByHash[prefab.name.GetStableHashCode()] = prefab;
                  db.m_recipes.Add(CreateRecipe(db, prefab));
                  ${P}.Log.LogInfo($"Registered {prefab.name} (cloned from {BasePrefab})");
              }

              private static GameObject GetOrCreate(GameObject source)
              {
                  if (_prefab || !source) return _prefab;
                  if (!_container)
                  {
                      // Inactive parent: the clone's Awake/ZNetView never run until the game instantiates it.
                      _container = new GameObject("${cls}_Prefabs");
                      _container.SetActive(false);
                      Object.DontDestroyOnLoad(_container);
                  }
                  _prefab = Object.Instantiate(source, _container.transform, false);
                  _prefab.name = ${P}.PrefabName;
                  return _prefab;
              }

              private static Recipe CreateRecipe(ObjectDB db, GameObject prefab)
              {
                  var template = db.GetRecipe(db.GetItemPrefab("${recipeFrom}").GetComponent<ItemDrop>().m_itemData);
                  var recipe = ScriptableObject.CreateInstance<Recipe>();
                  recipe.name = "Recipe_" + prefab.name;
                  recipe.m_item = prefab.GetComponent<ItemDrop>();
                  recipe.m_amount = 1;
                  recipe.m_craftingStation = template ? template.m_craftingStation : null;
                  recipe.m_minStationLevel = template ? template.m_minStationLevel + 1 : 1;
                  recipe.m_resources = new[]
                  {
                      ${reqs.map(([item, amount, per]) => `Requirement(db, "${item}", ${amount}, ${per}),`)}
                  };
                  return recipe;
              }

              private static Piece.Requirement Requirement(ObjectDB db, string item, int amount, int perLevel) => new Piece.Requirement
              {
                  m_resItem = db.GetItemPrefab(item).GetComponent<ItemDrop>(),
                  m_amount = amount,
                  m_amountPerLevel = perLevel,
                  m_recover = true,
              };
              ${
                status
                  ? code`

                    private static StatusEffect CreateStatus(ObjectDB db, ItemDrop.ItemData.SharedData shared)
                    {
                        var existing = db.GetStatusEffect(StatusName.GetStableHashCode());
                        if (existing) return existing;

                        var status = ScriptableObject.CreateInstance<SE_Stats>();
                        status.name = StatusName;
                        status.m_name = "$se_${snake}";
                        status.m_tooltip = "$se_${snake}_tooltip";
                        status.m_icon = shared.m_icons[0];
                        status.m_ttl = ${kind === "consumable" ? `${P}.DurationSeconds.Value` : "0f"};
                        status.m_healthRegenMultiplier = ${P}.RegenMultiplier.Value;
                        ${kind === "consumable" ? "" : `status.m_addMaxCarryWeight = ${P}.CarryWeight.Value;`}
                        ${dmgsOf(c).map((d) => `status.m_mods.Add(new HitData.DamageModPair { m_type = HitData.DamageType.${DMG_TYPE[d]}, m_modifier = HitData.DamageModifier.Resistant });`)}
                        db.m_StatusEffects.Add(status);
                        return status;
                    }`
                  : ""
              }
          }
      }`,
  );

  const desc = deriveFeatures(input)[0];
  return {
    settings,
    main,
    extra: kind === "weapon" ? [weaponHitPatch(c)] : kind === "consumable" ? [] : [abilityPatch(c)],
    words: {
      [`item_${snake}`]: displayName(c),
      [`item_${snake}_description`]: desc,
      ...(status ? { [`se_${snake}`]: displayName(c), [`se_${snake}_tooltip`]: `${desc}.` } : {}),
    },
    balance: itemBalance,
    tests: itemTests(c, elemental),
    prefab: cls,
  };
}

function magicArch(c: Ctx): ArchOut {
  const { cls, snake, P, B, n, input } = c;
  const base = c.fx.map((e) => STAFFS[e.key]).find(Boolean) ?? "StaffFireball";
  const dmgs = dmgsOf(c).length ? dmgsOf(c) : (["m_spirit"] as Dmg[]);
  const dmg = Number((n.power * 5).toFixed(1));
  const mats = [...new Set(c.fx.map((e) => VFX[e.key].mat))];
  const main = file(
    `src/Items/${cls}Staff.cs`,
    code`
      using Jotunn.Configs;
      using Jotunn.Entities;
      using Jotunn.Managers;
      using UnityEngine;

      namespace ${cls}.Items
      {
          /// <summary>Builds the staff from ${base} through Jötunn once vanilla prefabs are available.</summary>
          internal static class ${cls}Staff
          {
              private const string BasePrefab = "${base}";

              public static void Register()
              {
                  try
                  {
                      var staff = new CustomItem(${P}.PrefabName, BasePrefab, new ItemConfig
                      {
                          Name = "$item_${snake}",
                          Description = "$item_${snake}_description",
                          CraftingStation = CraftingStations.GaldrTable,
                          MinStationLevel = 2,
                          Requirements = new[]
                          {
                              new RequirementConfig("YggdrasilWood", 12, 4),
                              new RequirementConfig("Eitr", 16, 8),
                              ${mats.map((m) => `new RequirementConfig("${m}", 8, 4),`)}
                          },
                      });

                      var shared = staff.ItemDrop.m_itemData.m_shared;
                      ${dmgs.flatMap((d) => [`shared.m_damages.${d} = ${P}.SpellDamage.Value;`, `shared.m_damagesPerLevel.${d} = ${P}.SpellDamage.Value * ${B}.PerLevelRatio;`])}
                      shared.m_attack.m_attackEitr = ${P}.EitrCost.Value;
                      shared.m_equipStatusEffect = CreateAttunement(shared);

                      ItemManager.Instance.AddItem(staff);
                      ${P}.Log.LogInfo($"Added {staff.ItemDrop.name} (cloned from {BasePrefab})");
                  }
                  finally
                  {
                      PrefabManager.OnVanillaPrefabsAvailable -= Register;
                  }
              }

              /// <summary>Equip effect: faster eitr regeneration while the staff is in hand.</summary>
              private static StatusEffect CreateAttunement(ItemDrop.ItemData.SharedData shared)
              {
                  var attunement = ScriptableObject.CreateInstance<SE_Stats>();
                  attunement.name = "SE_${cls}";
                  attunement.m_name = "$se_${snake}";
                  attunement.m_tooltip = "$se_${snake}_tooltip";
                  attunement.m_icon = shared.m_icons[0];
                  attunement.m_eitrRegenMultiplier = ${P}.EitrRegen.Value;
                  ItemManager.Instance.AddStatusEffect(new CustomStatusEffect(attunement, fixReference: false));
                  return attunement;
              }
          }
      }`,
  );
  return {
    settings: [
      fl("Spell", "SpellDamage", dmg, "Elemental damage per projectile.", [1, 400]),
      nt("Spell", "EitrCost", 15 + n.radius * 2, "Eitr spent per cast.", [0, 150]),
      fl("Spell", "EitrRegen", Number((1 + n.intensity / 2).toFixed(2)), "Eitr regeneration multiplier while equipped.", [1, 3]),
      fl("Effects", "ProcChance", n.chance, "Chance for on-hit effects to trigger.", [0, 1]),
      fl("Effects", "Power", n.power, "Strength of the on-hit effects.", [1, 50]),
    ],
    main,
    extra: [weaponHitPatch(c)],
    words: {
      [`item_${snake}`]: displayName(c),
      [`item_${snake}_description`]: deriveFeatures(input)[0],
      [`se_${snake}`]: `${displayName(c)} attunement`,
      [`se_${snake}_tooltip`]: "Eitr flows faster while the staff is in hand.",
    },
    balance: itemBalance,
    tests: itemTests(c, dmg),
    prefab: cls,
    jotunn: true,
    awake: `PrefabManager.OnVanillaPrefabsAvailable += Items.${cls}Staff.Register;`,
  };
}

