/** Prompt keywords → vanilla prefab to clone, spawn biome and whether it eats meat. */
const CREATURES: [RegExp, string, string, boolean][] = [
  [/drake|dragon|wyvern|wyrm/, "Hatchling", "Mountain", true],
  [/wolf|wolves|hound|fenring/, "Wolf", "Mountain", true],
  [/boar|pig|hog/, "Boar", "Meadows", false],
  [/lox|mammoth/, "Lox", "Plains", false],
  [/troll|giant|ogre/, "Troll", "BlackForest", true],
  [/deer|stag|elk/, "Deer", "Meadows", false],
  [/serpent|eel|leviathan/, "Serpent", "Ocean", true],
  [/asksvin|askvin|lizard|raptor/, "Asksvin", "AshLands", true],
  [/seeker|spider|insect|bug/, "Seeker", "Mistlands", true],
  [/draugr|undead|zombie|ghoul/, "Draugr", "Swamp", true],
  [/skeleton|bone/, "Skeleton", "BlackForest", true],
  [/golem|stone/, "StoneGolem", "Mountain", true],
  [/wraith|ghost|phantom/, "Wraith", "Swamp", true],
  [/slime|blob|ooze/, "Blob", "Swamp", true],
