function entityArch(c: Ctx): ArchOut {
  const { cls, snake, P, n, k, input } = c;
  const ship = k === "vehicles" ? SHIPS.find(([re]) => re.test(c.text))?.[1] : undefined;
  if (ship) return shipArch(c, ship);

  const companion = k === "characters";
  const mount = k === "vehicles";
  const pick = CREATURES.find(([re]) => re.test(c.text)) ?? CREATURES.find(([, p]) => p === c.fx.map((e) => FX_CREATURE[e.key]).find(Boolean));
  const [, base, biome, meat] = companion ? [/./, "Dverger", "Mistlands", true] : mount ? (pick && /Lox|Asksvin/.test(pick[1]) ? pick : CREATURES[3]) : (pick ?? CREATURES[1]);
  const ride = mount || /\bride|riding|rideable|mount|saddle/.test(c.text);
  const tame = !companion && (ride || /tam(e|ing|able)|pet|companion|friend|loyal/.test(c.text));
  const weather = has(c, "frost") ? "SnowStorm" : has(c, "storm") ? "ThunderStorm" : "";
  const dmgs = dmgsOf(c);
  const Reg = companion ? "CompanionRegistration" : mount ? "MountRegistration" : "CreatureRegistration";
  const foods = meat ? ["RawMeat", "DeerMeat", "LoxMeat"] : ["Carrot", "Turnip", "Barley", "Cloudberry"];

  const settings: Setting[] = [
    fl(companion ? "Companion" : "Creature", "Health", n.health, "Base health before star scaling.", [10, 10000]),
    fl(companion ? "Companion" : "Creature", "SpeedBonus", n.speed, "Extra run speed as a fraction of the base creature.", [0, 2]),
    ...(dmgs.length ? [fl("Effects", "ElementalDamage", Number((n.power * 3).toFixed(1)), "Elemental damage added to every attack.", [0, 300])] : []),
    fl("Effects", "Power", n.power, "Strength of the creature's effects.", [1, 50]),
    ...(tame ? [fl("Taming", "TamingTime", n.duration * 150, "Seconds of feeding needed to tame.", [30, 7200])] : []),
    ...(ride ? [fl("Riding", "RideStamina", 120 + n.radius * 20, "Saddle stamina while ridden.", [20, 1000]), fl("Riding", "AbilityCooldown", n.cooldown, "Seconds between rider buffs.", [0.5, 120])] : []),
    ...(companion
      ? [
          hk("Hotkeys", "SummonKey", "H", "Summons your companion, or calls it back to you."),
          fl("Companion", "RegenPerSecond", Number((n.power / 2).toFixed(1)), "Health regained each second.", [0, 50]),
          fl("Companion", "AbilityCooldown", n.cooldown * 2, "Seconds between the companion's blessings on you.", [1, 120]),
        ]
      : [
          fl("Spawning", "SpawnChance", Math.round(n.chance * 100), "Percent chance per spawn check.", [0, 100]),
          nt("Spawning", "MaxSpawned", 1 + (n.interval % 3), "Most alive at once per spawn area.", [1, 10]),
          fl("Spawning", "SpawnInterval", n.interval * 60, "Seconds between spawn checks.", [30, 3600]),
