function audioArch(c: Ctx): ArchOut {
  const { cls, snake, P, n, input } = c;
  const [, biome] = biomeFor(c);
  const main = file(
    "src/Patches/MusicPatches.cs",
    code`
      using System.Collections;
      using System.Collections.Generic;
      using System.IO;
      using HarmonyLib;
      using UnityEngine;
      using UnityEngine.Networking;

      namespace ${cls}.Patches
      {
          /// <summary>
          /// Registers music/${snake}_day.ogg and music/${snake}_night.ogg as NamedMusic and points the ${biome}'s
          /// environment music at them, so MusicMan crossfades between them with the day cycle.
          /// </summary>
          [HarmonyPatch]
          public static class MusicPatches
          {
              public const string DayTrack = "${snake}_day";
              public const string NightTrack = "${snake}_night";
              private static readonly Dictionary<string, AudioClip> Clips = new Dictionary<string, AudioClip>();

              public static IEnumerator LoadTracks(string folder)
              {
                  foreach (var track in new[] { DayTrack, NightTrack })
                  {
                      var path = Path.Combine(folder, track + ".ogg");
                      if (!File.Exists(path))
                      {
                          ${P}.Log.LogWarning($"Missing {path}");
                          continue;
                      }
                      using (var request = UnityWebRequestMultimedia.GetAudioClip("file:///" + path.Replace('\\\\', '/'), AudioType.OGGVORBIS))
                      {
                          yield return request.SendWebRequest();
                          if (request.result != UnityWebRequest.Result.Success)
                          {
                              ${P}.Log.LogError($"{track}: {request.error}");
                              continue;
                          }
                          var clip = DownloadHandlerAudioClip.GetContent(request);
                          clip.name = track;
                          Clips[track] = clip;
                      }
                  }
                  if (MusicMan.instance) Register(MusicMan.instance);
              }

              [HarmonyPatch(typeof(MusicMan), nameof(MusicMan.Awake)), HarmonyPostfix]
              private static void MusicManAwake(MusicMan __instance) => Register(__instance);

              [HarmonyPatch(typeof(EnvMan), nameof(EnvMan.Awake)), HarmonyPostfix]
              private static void EnvManAwake(EnvMan __instance)
              {
                  if (!${P}.Enabled.Value) return;
                  foreach (var setup in __instance.m_biomes)
                  {
                      if (setup.m_biome != Heightmap.Biome.${biome}) continue;
                      setup.m_musicMorning = setup.m_musicDay = DayTrack;
                      setup.m_musicEvening = setup.m_musicNight = NightTrack;
                  }
              }

              private static void Register(MusicMan music)
              {
                  foreach (var pair in Clips)
                  {
                      if (music.m_music.Exists(m => m.m_name == pair.Key)) continue;
                      music.m_music.Add(new MusicMan.NamedMusic
                      {
                          m_name = pair.Key,
                          m_clips = new[] { pair.Value },
                          m_volume = ${P}.MusicVolume.Value,
                          m_fadeInTime = ${P}.FadeInSeconds.Value,
                          m_alwaysFadeout = true,
                          m_loop = true,
                          m_resume = true,
                          m_enabled = true,
                          m_ambientMusic = true,
                      });
                      ${P}.Log.LogInfo($"Registered music {pair.Key} ({pair.Value.length:0}s)");
                  }
              }
          }
      }`,
  );
  return {
    settings: [
      fl("Music", "MusicVolume", 0.8, "Volume of the new tracks.", [0, 1]),
      fl("Music", "FadeInSeconds", n.duration, "Crossfade time when the day cycle switches tracks.", [0, 30]),
    ],
    main,
    extra: [],
    words: { [`${snake}_title`]: input.modName },
    balance: tickBalance,
    tests: tickTests(c),
    usings: ["using System.IO;"],
    awake: `StartCoroutine(Patches.MusicPatches.LoadTracks(Path.Combine(Path.GetDirectoryName(Info.Location), "music")));`,
    refs: ["UnityEngine.AudioModule", "UnityEngine.UnityWebRequestModule", "UnityEngine.UnityWebRequestAudioModule"],
  };
}

