                  ${onHit(c, "__instance", "attacker", `${P}.Power.Value`, false)}
              }

              private static bool IsOurs(Character character) =>
                  character && ${P}.Enabled.Value && Utils.GetPrefabName(character.gameObject) == ${P}.PrefabName;
          }
      }`,
  );

  const spawn = file(
    "src/Patches/SpawnSystemPatch.cs",
    code`
      using System.Collections.Generic;
      using HarmonyLib;

      namespace ${cls}.Patches
      {
          /// <summary>Every zone's SpawnSystem shares the same SpawnSystemList asset, so the entry is added once.</summary>
          [HarmonyPatch(typeof(SpawnSystem), nameof(SpawnSystem.Awake))]
          public static class SpawnSystemPatch
          {
              private static void Postfix(SpawnSystem __instance)
              {
                  if (!${P}.Enabled.Value || __instance.m_spawnLists.Count == 0) return;
                  var spawners = __instance.m_spawnLists[0].m_spawners;
                  if (spawners.Exists(s => s.m_name == ${P}.PrefabName)) return;

                  var prefab = ZNetScene.instance.GetPrefab(${P}.PrefabName);
                  if (!prefab) return;
                  spawners.Add(new SpawnSystem.SpawnData
                  {
                      m_name = ${P}.PrefabName,
                      m_prefab = prefab,
                      m_enabled = true,
                      m_biome = Heightmap.Biome.${biome},
                      m_biomeArea = Heightmap.BiomeArea.Everything,
                      m_maxSpawned = ${P}.MaxSpawned.Value,
                      m_spawnInterval = ${P}.SpawnInterval.Value,
                      m_spawnChance = ${P}.SpawnChance.Value,
                      m_spawnDistance = 40f,
                      m_groupSizeMin = 1,
                      m_groupSizeMax = ${mount ? 3 : 2},
                      m_spawnAtDay = ${has(c, "lunar") || has(c, "void") ? "false" : "true"},
                      m_spawnAtNight = true,
                      m_minLevel = 1,
                      m_maxLevel = 3,
                      ${weather ? `m_requiredEnvironments = new List<string> { "${weather}" },` : ""}
                      ${biome === "Ocean" ? "m_minAltitude = -1000f,\nm_maxAltitude = -2f," : "m_minAltitude = 0f,"}
                  });
              }
          }
      }`,
  );

  const summon = file(
    "src/Patches/CompanionSummonPatch.cs",
    code`
      using HarmonyLib;
      using UnityEngine;
      using Object = UnityEngine.Object;

      namespace ${cls}.Patches
      {
          [HarmonyPatch(typeof(Player), nameof(Player.Update))]
          public static class CompanionSummonPatch
          {
              private static void Postfix(Player __instance)
              {
                  if (__instance != Player.m_localPlayer || !${P}.Enabled.Value || !__instance.TakeInput() || !${P}.SummonKey.Value.IsDown()) return;

                  var existing = Character.GetAllCharacters().Find(ch => ch.IsTamed() && Utils.GetPrefabName(ch.gameObject) == ${P}.PrefabName);
                  if (existing)
                  {
                      existing.GetComponent<MonsterAI>().SetFollowTarget(__instance.gameObject);
                      __instance.Message(MessageHud.MessageType.Center, "$enemy_${snake}_follow");
                      return;
                  }

                  var spawnPos = __instance.transform.position + __instance.transform.forward * 2f;
                  var go = Object.Instantiate(ZNetScene.instance.GetPrefab(${P}.PrefabName), spawnPos, __instance.transform.rotation);
                  go.GetComponent<Character>().SetTamed(true);
                  go.GetComponent<MonsterAI>().SetFollowTarget(__instance.gameObject);
                  __instance.Message(MessageHud.MessageType.Center, "$enemy_${snake}_summoned");
              }
          }
      }`,
  );

  return {
    settings,
    main,
    extra: companion ? [attack, summon] : mount ? [spawn] : [spawn, attack],
    words: {
      [`enemy_${snake}`]: displayName(c, true),
      ...(companion ? { [`enemy_${snake}_follow`]: `${displayName(c, true)} falls in beside you`, [`enemy_${snake}_summoned`]: `${displayName(c, true)} answers your call` } : {}),
    },
    balance: entityBalance,
    tests: code`
