      [InlineData(1, ${n.health}f)]
      [InlineData(3, ${n.health * 3}f)]
      public void HealthScalesWithStars(int level, float expected) =>
          Assert.Equal(expected, ${c.B}.HealthAtLevel(${n.health}f, level));

      [Fact]
      public void TamingNeverGoesNegative() =>
          Assert.Equal(0f, ${c.B}.TamingLeft(${n.duration * 150}f, ${n.duration * 300}f));`,
    prefab: cls,
  };
}

function shipArch(c: Ctx, base: string): ArchOut {
  const { cls, snake, P, n, input } = c;
  const fly = has(c, "flight");
  const mat = VFX[c.fx[0].key].mat;
  const main = file(
    "src/Patches/ShipRegistration.cs",
    code`
      using HarmonyLib;
      using UnityEngine;
      using Object = UnityEngine.Object;

      namespace ${cls}.Patches
      {
          /// <summary>Clones ${base} into a buildable ship and adds it to the Hammer's piece table.</summary>
          [HarmonyPatch]
          public static class ShipRegistration
          {
              private const string BasePrefab = "${base}";
              private static GameObject _prefab;
              private static GameObject _container;

              [HarmonyPatch(typeof(ZNetScene), nameof(ZNetScene.Awake)), HarmonyPostfix]
              private static void ZNetSceneAwake(ZNetScene __instance)
              {
                  var source = __instance.GetPrefab(BasePrefab);
                  if (!source || __instance.GetPrefab(${P}.PrefabName)) return;
                  if (!_container)
                  {
                      _container = new GameObject("${cls}_Prefabs");
                      _container.SetActive(false);
                      Object.DontDestroyOnLoad(_container);
                  }
                  _prefab = Object.Instantiate(source, _container.transform, false);
                  _prefab.name = ${P}.PrefabName;

                  var ship = _prefab.GetComponent<Ship>();
                  ship.m_sailForceFactor *= ${P}.SailForce.Value;
                  ship.m_stearForce *= ${P}.Steering.Value;
                  ship.m_backwardForce *= ${P}.Steering.Value;
                  _prefab.GetComponent<WearNTear>().m_health = ${P}.HullHealth.Value;

                  var piece = _prefab.GetComponent<Piece>();
                  piece.m_name = "$piece_${snake}";
                  piece.m_description = "$piece_${snake}_description";
                  piece.m_resources = new[]
                  {
                      Requirement(__instance, "FineWood", 40),
                      Requirement(__instance, "ElderBark", 40),
                      Requirement(__instance, "IronNails", 80),
                      Requirement(__instance, "DeerHide", 10),
                      Requirement(__instance, "${mat}", 8),
                  };

                  __instance.m_prefabs.Add(_prefab);
                  __instance.m_namedPrefabs[_prefab.name.GetStableHashCode()] = _prefab;
                  AddToHammer(ObjectDB.instance);
              }

              [HarmonyPatch(typeof(ObjectDB), nameof(ObjectDB.Awake)), HarmonyPostfix]
              private static void ObjectDBAwake(ObjectDB __instance) => AddToHammer(__instance);

              private static void AddToHammer(ObjectDB db)
              {
                  if (!_prefab || !db) return;
                  var hammer = db.GetItemPrefab("Hammer");
                  var pieces = hammer ? hammer.GetComponent<ItemDrop>().m_itemData.m_shared.m_buildPieces.m_pieces : null;
                  if (pieces != null && !pieces.Contains(_prefab)) pieces.Add(_prefab);
              }

              private static Piece.Requirement Requirement(ZNetScene scene, string item, int amount) => new Piece.Requirement
              {
                  m_resItem = scene.GetPrefab(item).GetComponent<ItemDrop>(),
                  m_amount = amount,
                  m_recover = true,
              };
          }
      }`,
  );
  const physics = file(
    "src/Patches/ShipPhysicsPatch.cs",
    code`
      using HarmonyLib;
      using UnityEngine;

      namespace ${cls}.Patches
      {
          /// <summary>Ship physics run on the owner (the helmsman), so forces are only added there.</summary>
          [HarmonyPatch(typeof(Ship), nameof(Ship.CustomFixedUpdate))]
          public static class ShipPhysicsPatch
          {
              private static void Postfix(Ship __instance)
              {
                  if (!${P}.Enabled.Value || !__instance.m_nview.IsOwner() || Utils.GetPrefabName(__instance.gameObject) != ${P}.PrefabName) return;

                  if (__instance.GetSpeedSetting() == Ship.Speed.Full)
                  {
                      // The sails bite harder in storm weather (ThunderStorm, SnowStorm, Ashlands storms).
                      bool storm = EnvMan.instance.GetCurrentEnvironment()?.m_name.Contains("Storm") == true;
                      __instance.m_body.AddForce(__instance.transform.forward * ${c.B}.SailBoost(${P}.FullSailBoost.Value, storm), ForceMode.Acceleration);
                  }
                  ${
                    fly
                      ? code`

                        // Lift while crewed: the hull rides a few meters above the swell.
                        if (__instance.HasPlayerOnboard() && __instance.transform.position.y < ZoneSystem.instance.m_waterLevel + ${P}.HoverHeight.Value)
                            __instance.m_body.AddForce(Vector3.up * (-Physics.gravity.y * 1.15f), ForceMode.Acceleration);`
                      : ""
                  }
              }
          }
      }`,
  );
  return {
    settings: [
      fl("Ship", "SailForce", Number((1 + n.speed).toFixed(2)), "Sail force multiplier.", [0.5, 4]),
      fl("Ship", "Steering", Number((1 + n.speed / 2).toFixed(2)), "Rudder and reverse force multiplier.", [0.5, 4]),
      fl("Ship", "HullHealth", n.health * 2, "Hull hit points.", [100, 20000]),
      fl("Ship", "FullSailBoost", Number((n.speed * 4).toFixed(2)), "Extra forward acceleration at full sail.", [0, 10]),
      ...(fly ? [fl("Ship", "HoverHeight", n.radius, "Meters above the water the hull hovers when crewed.", [1, 30])] : []),
    ],
    main,
    extra: [physics],
    words: { [`piece_${snake}`]: displayName(c, true), [`piece_${snake}_description`]: deriveFeatures(input)[0] },
    balance: code`
      /// <summary>Extra full-sail acceleration; storms double it.</summary>
      public static float SailBoost(float boost, bool storm) => storm ? boost * 2f : boost;`,
    tests: code`
      [Theory]
      [InlineData(false, ${Number((n.speed * 4).toFixed(2))}f)]
      [InlineData(true, ${Number((n.speed * 8).toFixed(2))}f)]
      public void StormsDoubleTheSailBoost(bool storm, float expected) =>
          Assert.Equal(expected, ${c.B}.SailBoost(${Number((n.speed * 4).toFixed(2))}f, storm), 3);`,
    prefab: cls,
    refs: ["UnityEngine.PhysicsModule"],
  };
}

/* ───────────── world: Jötunn ZoneManager locations + vanilla vegetation and biome checks ───────────── */

const biomeFor = (c: Ctx) => BIOMES.find(([re]) => re.test(c.text))!;

const tickBalance = code`
  /// <summary>Extra strength while EnvMan reports night.</summary>
  public const float NightBonus = 1.5f;

  public static bool Ready(float timer, float interval) => timer >= System.Math.Max(0.25f, interval);

  public static float NightScaled(float power, bool night) => night ? power * NightBonus : power;`;

function tickTests(c: Ctx) {
  return code`
    [Fact]
    public void IntervalHasAFloor() => Assert.True(${c.B}.Ready(0.25f, 0f));

    [Fact]
    public void WaitsForTheConfiguredInterval() => Assert.False(${c.B}.Ready(${c.n.interval - 0.5}f, ${c.n.interval}f));

    [Theory]
    [InlineData(false, ${c.n.power}f)]
    [InlineData(true, ${Number((c.n.power * 1.5).toFixed(2))}f)]
    public void NightBoostsPower(bool night, float expected) =>
        Assert.Equal(expected, ${c.B}.NightScaled(${c.n.power}f, night), 3);`;
}

function worldArch(c: Ctx): ArchOut {
  const { cls, snake, P, B, n, input } = c;
  const [, biome, location, chest, veg] = biomeFor(c);
  const main = file(
    `src/World/${cls}Locations.cs`,
    code`
      using Jotunn.Managers;
      using UnityEngine;
      using Object = UnityEngine.Object;

      namespace ${cls}.World
      {
          /// <summary>Clones ${location} into a new ${biome} location once ZoneSystem has loaded the vanilla ones.</summary>
          internal static class ${cls}Locations
          {
              private const string BaseLocation = "${location}";

              public static void Register()
              {
                  try
                  {
                      var location = ZoneManager.Instance.CreateClonedLocation(${P}.PrefabName, BaseLocation);
                      var zone = location.ZoneLocation;
                      zone.m_biome = Heightmap.Biome.${biome};
                      zone.m_biomeArea = Heightmap.BiomeArea.Everything;
                      zone.m_quantity = ${B}.ScaledQuantity(${P}.LocationQuantity.Value, 1f);
                      zone.m_prioritized = true;
                      zone.m_minAltitude = ${P}.MinAltitude.Value;
                      zone.m_minDistanceFromSimilar = ${n.interval * 64}f;
                      zone.m_iconPlaced = true;

                      // Dress the clone with a vanilla chest so it is worth the detour.
                      var loot = PrefabManager.Instance.GetPrefab("${chest}");
                      if (loot)
                      {
                          var prop = Object.Instantiate(loot, location.Prefab.transform);
                          prop.name = loot.name;
                          prop.transform.localPosition = new Vector3(1.5f, 0f, 2f);
                      }
                      ${P}.Log.LogInfo($"Added location {location.Name} to {zone.m_biome} x{zone.m_quantity}");
                  }
                  finally
                  {
                      ZoneManager.OnVanillaLocationsAvailable -= Register;
                  }
              }
          }
      }`,
  );
  const vegetation = file(
    "src/Patches/VegetationPatch.cs",
    code`
      using HarmonyLib;

      namespace ${cls}.Patches
      {
          /// <summary>Thickens ${biome} vegetation. Only affects zones generated after install.</summary>
          [HarmonyPatch(typeof(ZoneSystem), nameof(ZoneSystem.Awake))]
          public static class VegetationPatch
          {
              private static readonly string[] Tracked = { ${veg.map((v) => `"${v}"`).join(", ")} };

              private static void Postfix(ZoneSystem __instance)
              {
                  if (!${P}.Enabled.Value) return;
                  var density = ${P}.VegetationDensity.Value;
                  foreach (ZoneSystem.ZoneVegetation vegetation in __instance.m_vegetation)
                  {
                      if (!vegetation.m_enable || !vegetation.m_prefab || (vegetation.m_biome & Heightmap.Biome.${biome}) == 0) continue;
                      if (System.Array.IndexOf(Tracked, vegetation.m_prefab.name) < 0) continue;
                      vegetation.m_min *= density;
                      vegetation.m_max *= density;
                      vegetation.m_groupSizeMax = ${B}.ScaledQuantity(vegetation.m_groupSizeMax, density);
                  }
              }
          }
      }`,
  );
  const aura = file(
    "src/Patches/BiomeAuraPatch.cs",
    code`
      using System.Collections.Generic;
      using HarmonyLib;
      using UnityEngine;
      using Object = UnityEngine.Object;

      namespace ${cls}.Patches
      {
          /// <summary>While the local player is in the ${biome}, the land pulses ${c.fx[0].label.toLowerCase()}.</summary>
          [HarmonyPatch(typeof(Player), nameof(Player.Update))]
          public static class BiomeAuraPatch
          {
              private static float _timer;
              private static bool _inside;

              private static void Postfix(Player __instance)
              {
                  if (__instance != Player.m_localPlayer || !${P}.Enabled.Value || __instance.IsDead()) return;

                  bool inside = __instance.GetCurrentBiome() == Heightmap.Biome.${biome};
                  if (inside && !_inside) __instance.Message(MessageHud.MessageType.Center, "$location_${snake}_enter");
                  _inside = inside;
                  if (!inside) return;

                  _timer += Time.deltaTime;
                  if (!${B}.Ready(_timer, ${P}.AuraInterval.Value)) return;
                  _timer = 0f;
                  ${has(c, "lunar") ? "if (!EnvMan.instance.IsNight()) return;" : ""}

                  ${castBlock(c, "__instance", `${P}.Power.Value`, `${P}.Radius.Value`, true).trim() || `__instance.AddStamina(${P}.Power.Value);`}
              }
          }
