  return {
    settings: [
      nt("Location", "LocationQuantity", n.interval * 8, "How many copies ZoneSystem tries to place per world.", [1, 400]),
      fl("Location", "MinAltitude", biome === "Mountain" ? 80 : 2, "Lowest terrain height a copy may be placed at.", [-100, 500]),
      fl("Vegetation", "VegetationDensity", Number((1 + n.chance * 2).toFixed(2)), "Multiplier for the tracked vegetation.", [0.1, 5]),
      fl("Biome", "AuraInterval", n.interval, "Seconds between aura pulses.", [1, 120]),
      fl("Biome", "Radius", n.radius, "Aura radius in meters.", [1, 30]),
      fl("Effects", "Power", n.power, "Strength of the aura's effects.", [1, 50]),
    ],
    main,
    extra: [vegetation, aura],
    words: { [`location_${snake}`]: input.modName, [`location_${snake}_enter`]: `You enter the ${input.modName}` },
    balance: code`
      ${tickBalance}

      public static int ScaledQuantity(int quantity, float density) => System.Math.Max(1, (int)System.Math.Round(quantity * Clamp(density, 0.1f, 5f)));`,
    tests: code`
      ${tickTests(c)}

      [Theory]
      [InlineData(1f, ${n.interval * 8})]
      [InlineData(100f, ${n.interval * 40})]
      public void QuantityScalesWithDensityUpToFiveTimes(float density, int expected) =>
          Assert.Equal(expected, ${c.B}.ScaledQuantity(${n.interval * 8}, density));`,
    prefab: `${cls}_Location`,
    jotunn: true,
    awake: `ZoneManager.OnVanillaLocationsAvailable += World.${cls}Locations.Register;`,
  };
}

/* ───────────── system: mechanics, quests, interface, audio ───────────── */

const QUEST_TARGETS: Partial<Record<EffectKey, string[]>> = {
  frost: ["Wolf", "Hatchling", "Fenring"],
  fire: ["Surtling", "Goblin", "GoblinBrute"],
  poison: ["Blob", "Draugr", "Leech"],
  void: ["Skeleton", "Ghost", "Wraith"],
  lunar: ["Skeleton", "Ghost", "Wraith"],
};

function systemArch(c: Ctx): ArchOut {
  const { k } = c;
  if (k === "quests") return questArch(c);
  if (k === "interface") return interfaceArch(c);
  if (k === "audio") return audioArch(c);
  return mechanicsArch(c);
}

function mechanicsArch(c: Ctx): ArchOut {
  const { cls, snake, P, B, n, input } = c;
  if (c.fx[0].key === "auto") {
    return {
      settings: [fl("Automation", "FeedRadius", n.radius, "Radius in meters searched for chests to feed smelters and kilns from.", [1, 20])],
      main: productionPatch(c),
      extra: [feederPatch(c)],
      words: { [`${snake}_title`]: input.modName },
      balance: "",
      tests: "",
      refs: ["UnityEngine.PhysicsModule"],
    };
  }
  const radius = `${P}.Radius.Value`;
  const passive = castBlock(c, "player", "power", radius, true).trim();
  const burst = castBlock(c, "player", "power", radius).trim();
  const split = passive !== burst;
  const pulse = file(
    "src/Patches/PlayerUpdatePatch.cs",
    code`
      using System.Collections.Generic;
      using HarmonyLib;
      using UnityEngine;
      using Object = UnityEngine.Object;

      namespace ${cls}.Patches
      {
          /// <summary>${passive ? "A passive pulse every Interval seconds, plus an active burst on the hotkey." : "An active burst on the hotkey."}</summary>
          [HarmonyPatch(typeof(Player), nameof(Player.Update))]
          public static class PlayerUpdatePatch
          {
              ${passive ? "private static float _timer;" : ""}
              private static float _cooldown;

              private static void Postfix(Player __instance)
              {
                  if (__instance != Player.m_localPlayer || !${P}.Enabled.Value || __instance.IsDead()) return;
                  _cooldown -= Time.deltaTime;
                  ${
                    passive
                      ? code`
                        _timer += Time.deltaTime;
                        if (${B}.Ready(_timer, ${P}.Interval.Value))
                        {
                            _timer = 0f;
                            Pulse(__instance, ${B}.NightScaled(${P}.Power.Value, EnvMan.instance.IsNight()));
                        }
                        `
                      : ""
                  }
                  if (_cooldown <= 0f && __instance.TakeInput() && ${P}.AbilityKey.Value.IsDown())
                  {
                      _cooldown = ${P}.AbilityCooldown.Value;
                      ${split ? "Burst" : "Pulse"}(__instance, ${P}.Power.Value * 2f);
                      __instance.Message(MessageHud.MessageType.TopLeft, "$${snake}_burst");
                  }
              }
              ${
                passive
                  ? code`

                    private static void Pulse(Player player, float power)
                    {
                        ${passive}
                    }`
                  : ""
              }
              ${
                split
                  ? code`

                    private static void Burst(Player player, float power)
                    {
                        ${burst}
                    }`
                  : ""
              }
          }
      }`,
  );
  return {
    settings: [
      ...(passive ? [fl("General", "Interval", n.interval, "Seconds between passive pulses.", [1, 120])] : []),
      fl("Effects", "Power", n.power, "Strength of each pulse.", [1, 50]),
      fl("Effects", "Radius", n.radius, "Pulse radius in meters.", [1, 30]),
      hk("Hotkeys", "AbilityKey", "G", "Fires a double-strength pulse."),
      fl("Hotkeys", "AbilityCooldown", n.cooldown, "Seconds between bursts.", [0.5, 120]),
    ],
    main: pulse,
    extra: [],
    words: { [`${snake}_burst`]: `${input.modName}!` },
    balance: tickBalance,
    tests: tickTests(c),
  };
}

function questArch(c: Ctx): ArchOut {
  const { cls, snake, P, B, n, input } = c;
  const targets = c.fx.map((e) => QUEST_TARGETS[e.key]).find(Boolean) ?? ["Greydwarf", "Troll", "Draugr"];
  const finalReward = VFX[c.fx[0].key].mat;
  const perStage = Math.max(3, Math.round(n.xp / 8));
  const nightOnly = has(c, "lunar") || has(c, "void");
  const main = file(
    "src/Patches/QuestTracker.cs",
    code`
      using HarmonyLib;
      using UnityEngine;
      using Object = UnityEngine.Object;

      namespace ${cls}.Patches
      {
          /// <summary>
          /// Three hunting stages, saved in Player.m_customData so progress survives logout.
          /// Character.OnDeath runs on the ZDO owner, which is usually the nearest player.
          /// </summary>
          [HarmonyPatch]
          public static class QuestTracker
          {
              public const string KillsKey = "com.cyrus.${snake}.kills";
              public static readonly string[] Targets = { ${targets.map((t) => `"${t}"`).join(", ")} };
              private static readonly string[] Rewards = { "Coins", "Coins", "${finalReward}" };

              [HarmonyPatch(typeof(Character), nameof(Character.OnDeath)), HarmonyPostfix]
              private static void OnDeath(Character __instance)
              {
                  var player = Player.m_localPlayer;
                  if (!player || !${P}.Enabled.Value || __instance.m_lastHit?.GetAttacker() != player) return;
                  ${nightOnly ? "if (!EnvMan.instance.IsNight()) return; // the hunt only counts under the moon" : ""}

                  int kills = Kills(player);
                  int perStage = ${P}.KillsPerStage.Value;
                  int stage = ${B}.StageFor(kills, perStage, Targets.Length);
                  if (stage >= Targets.Length || Utils.GetPrefabName(__instance.gameObject) != Targets[stage]) return;

                  kills++;
                  player.m_customData[KillsKey] = kills.ToString();
                  if (${B}.StageFor(kills, perStage, Targets.Length) == stage)
                  {
                      MessageHud.instance.ShowMessage(MessageHud.MessageType.TopLeft,
                          Localization.instance.Localize("$${snake}_progress", ${B}.ProgressInStage(kills, perStage).ToString(), perStage.ToString()));
                      return;
                  }

                  Reward(player, stage);
                  if (stage + 1 < Targets.Length)
                  {
                      var next = ZNetScene.instance.GetPrefab(Targets[stage + 1]).GetComponent<Character>().m_name;
                      MessageHud.instance.ShowMessage(MessageHud.MessageType.Center,
                          Localization.instance.Localize("$${snake}_stage", (stage + 2).ToString(), Localization.instance.Localize(next)));
                  }
              }

              public static int Kills(Player player) =>
                  player.m_customData.TryGetValue(KillsKey, out var raw) && int.TryParse(raw, out var kills) ? kills : 0;

              private static void Reward(Player player, int stage)
              {
                  var prefab = ObjectDB.instance.GetItemPrefab(Rewards[stage]);
                  var drop = Object.Instantiate(prefab, player.transform.position + Vector3.up, Quaternion.identity).GetComponent<ItemDrop>();
                  drop.SetStack(${P}.RewardAmount.Value * (stage + 1));
                  MessageHud.instance.QueueUnlockMsg(drop.m_itemData.GetIcon(), "$${snake}_title", stage + 1 == Targets.Length ? "$${snake}_complete" : "$${snake}_stage_done");
                  ${selfs(c, "player", `${P}.Power.Value`, true, ["blink"])}
              }
          }
      }`,
  );
  const command = file(
    "src/Patches/QuestCommand.cs",
    code`
      using HarmonyLib;

      namespace ${cls}.Patches
      {
          /// <summary>Adds a "${snake}" console command that prints quest progress.</summary>
          [HarmonyPatch(typeof(Terminal), nameof(Terminal.InitTerminal))]
          public static class QuestCommand
          {
              private static void Postfix()
              {
                  new Terminal.ConsoleCommand("${snake}", "shows ${input.modName} progress", args =>
                  {
                      var player = Player.m_localPlayer;
                      if (!player) return;
                      int kills = QuestTracker.Kills(player);
                      int stage = ${B}.StageFor(kills, ${P}.KillsPerStage.Value, QuestTracker.Targets.Length);
                      args.Context.AddString(stage >= QuestTracker.Targets.Length
                          ? $"{${P}.PluginName}: complete"
                          : $"{${P}.PluginName}: stage {stage + 1}, {QuestTracker.Targets[stage]} {${B}.ProgressInStage(kills, ${P}.KillsPerStage.Value)}/{${P}.KillsPerStage.Value}");
                  });
              }
          }
      }`,
  );
  return {
    settings: [
      nt("Quest", "KillsPerStage", perStage, "Kills needed to clear each stage.", [1, 100]),
      nt("Quest", "RewardAmount", n.xp, "Base reward stack, multiplied by the stage number.", [1, 999]),
      fl("Effects", "Power", n.power, "Strength of the stage-clear blessing.", [1, 50]),
    ],
    main,
    extra: [command],
    words: {
      [`${snake}_title`]: input.modName,
      [`${snake}_stage`]: "Stage $1: hunt the $2",
      [`${snake}_progress`]: `${input.modName}: $1 / $2`,
      [`${snake}_stage_done`]: "Stage cleared. The gods take notice.",
      [`${snake}_complete`]: "The saga is complete.",
    },
    balance: code`
      public static int StageFor(int kills, int perStage, int stages) => System.Math.Min(stages, kills / System.Math.Max(1, perStage));

      public static int ProgressInStage(int kills, int perStage) => kills % System.Math.Max(1, perStage);`,
    tests: code`
      [Theory]
      [InlineData(0, 0)]
      [InlineData(${perStage}, 1)]
      [InlineData(${perStage * 9}, 3)]
      public void StagesAdvanceAndCap(int kills, int expected) =>
          Assert.Equal(expected, ${c.B}.StageFor(kills, ${perStage}, 3));

      [Fact]
      public void ZeroPerStageDoesNotDivideByZero() => Assert.Equal(3, ${c.B}.StageFor(5, 0, 3));`,
  };

