/**
 * Writes a matrix of Cyrus-generated Valheim mods to disk so run.sh can compile each one against the
 * REAL game assemblies and run the generated xUnit tests. Covers every archetype the generator has
 * (weapon, consumable, tool, trinket, staff, creature, tameable mount, companion, ship, each biome
 * location, automation, pulse mechanic, quest, HUD, music, color grade) for the Yakko (full) and
 * Katara (3-file) outputs, plus a v2 refinement.
 *
 *   npx tsx tools/cyrus-valheim-harness/generate.ts OUT_DIR
 *
 * Also runs the static validator on every mod and writes OUT_DIR/matrix.json.
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { CATEGORY_BY_KEY, GAME_BY_ID } from "../../lib/cyrus/data";
import { buildModFiles } from "../../lib/cyrus/engine/templates";
import { validateValheimMod } from "../../lib/cyrus/games/valheim.validate";
import type { CategoryKey, ModelId } from "../../lib/cyrus/types";

type Case = { id: string; category: CategoryKey; modName: string; prompt: string; model: ModelId; version?: number };

const base: Omit<Case, "id" | "model">[] = [
  { category: "weapons", modName: "Frostbite Blade", prompt: "an iron sword that freezes and slows enemies" },
  { category: "weapons", modName: "Storm Bow", prompt: "a bow that calls down lightning on hit" },
  { category: "items", modName: "Honey Mead", prompt: "a healing mead potion that regenerates health" },
  { category: "items", modName: "Ember Pickaxe", prompt: "a fire pickaxe tool for mining" },
  { category: "items", modName: "Wolf Belt", prompt: "a trinket belt that lets you blink forward" },
  { category: "magic", modName: "Void Staff", prompt: "a shadow staff that drains enemies" },
  { category: "creatures", modName: "Storm Drake", prompt: "tameable rideable drakes with lightning" },
  { category: "creatures", modName: "Bog Horror", prompt: "a poison swamp boss that summons minions" },
  { category: "characters", modName: "Shieldmaiden", prompt: "a companion that heals you" },
  { category: "vehicles", modName: "Sky Drakkar", prompt: "a flying longship" },
  { category: "vehicles", modName: "War Lox", prompt: "a lox mount you can ride" },
  { category: "worlds", modName: "Frozen Peaks", prompt: "icy mountain ruins" },
  { category: "worlds", modName: "Jotun Wastes", prompt: "deep north frozen tundra camps" },
  { category: "worlds", modName: "Ember Plains", prompt: "fire ruins across the plains" },
  { category: "worlds", modName: "Rot Marsh", prompt: "toxic swamp crypts" },
  { category: "worlds", modName: "Elder Grove", prompt: "a shadow forest" },
  { category: "worlds", modName: "Green Hollow", prompt: "a peaceful meadow village" },
  { category: "mechanics", modName: "Auto Smelter", prompt: "automate smelting and farming from nearby chests" },
  { category: "mechanics", modName: "Moon Pulse", prompt: "a lunar aura that pulses at night" },
  { category: "quests", modName: "Wolf Hunt", prompt: "a frost questline hunting wolves" },
  { category: "interface", modName: "Viking Radar", prompt: "a hud overlay showing nearby hostiles" },
  { category: "audio", modName: "Night Songs", prompt: "new music for the meadows at night" },
  { category: "shaders", modName: "Aurora Grade", prompt: "an aurora color grade with bloom" },
];

const cases: Case[] = [];
for (const b of base) {
  const slug = b.modName.toLowerCase().replace(/[^a-z0-9]+/g, "-");
  cases.push({ ...b, id: `${slug}-yakko`, model: "yakko" });
  cases.push({ ...b, id: `${slug}-katara`, model: "katara" });
}
cases.push({ ...base[0], id: "frostbite-blade-saka-v2", model: "saka", version: 2 });

const out = process.argv[2];
if (!out) throw new Error("usage: generate.ts OUT_DIR");
const game = GAME_BY_ID.valheim;
const matrix: unknown[] = [];
let blocked = 0;
for (const c of cases) {
  const input = { game, category: CATEGORY_BY_KEY[c.category], modName: c.modName, prompt: c.prompt, model: c.model, version: c.version ?? 1 };
  const files = buildModFiles(input);
  const dir = join(out, c.id);
  for (const f of files) {
    const p = join(dir, f.path);
    mkdirSync(dirname(p), { recursive: true });
    writeFileSync(p, f.content);
  }
  const report = validateValheimMod(files);
  if (!report.ok) blocked++;
  const csproj = files.find((f) => f.path.endsWith(".csproj") && !f.path.startsWith("tests/"))?.path ?? null;
  const tests = files.find((f) => f.path.startsWith("tests/") && f.path.endsWith(".csproj"))?.path ?? null;
  matrix.push({ id: c.id, model: c.model, category: c.category, csproj, tests, files: files.length, validator: { ok: report.ok, side: report.side, issues: report.issues } });
}
writeFileSync(join(out, "matrix.json"), JSON.stringify(matrix, null, 2));
console.log(`generated ${cases.length} mods into ${out}; validator blocked ${blocked}`);
if (blocked) process.exitCode = 1;

