new='''import { VALHEIM_SIDE_NOTE, VALHEIM_TARGET, valheimModSide, type ValheimSide } from "@/lib/cyrus/games/valheim";

/* ═════════════ Valheim 1.0 · BepInEx 5 · HarmonyX · C# (Jötunn for content and version enforcement) ═════════════
 *
 * Every game member used below was re-checked against the Valheim 1.0.16 dedicated-server assemblies and
 * every template is compiled against them by tools/cyrus-valheim-harness/run.sh. Prefab, location,
 * vegetation and status-effect names were checked against Jötunn's vanilla lists (generated from 1.0.7).
 * Private members (m_nview, Player.Update, Smelter.Awake...) are reachable because the csproj publicizes
 * assembly_valheim at compile time; nothing is reflected at runtime.
 */

type Dmg = "m_frost" | "m_fire" | "m_lightning" | "m_poison" | "m_spirit";

/** Valheim code per effect. TARGET is the Character being hit, SOURCE the attacker, POWER a float expression. */
interface VFx {
  /** HitData.DamageTypes field the effect adds. */
  dmg?: Dmg;
  /** Vanilla crafting material its recipes ask for. */
  mat: string;
  hit?: string;
  /** Runs once per proc on SOURCE. */
  self?: string;
  /** `self` only compiles when SOURCE is a Player. */
  player?: boolean;
}

/** SEMan routes the add through RPC_AddStatusEffect when this client does not own the character, so it is multiplayer-safe. */
const addSE = (hash: string, on = "TARGET") => `${on}.GetSEMan().AddStatusEffect(${hash}, resetTime: true)`;

const VFX: Record<EffectKey, VFx> = {
  frost: { dmg: "m_frost", mat: "FreezeGland", hit: `${addSE("SEMan.s_statusEffectFrost")};` },
  // Burning/Poison only return the effect on the owning client; elsewhere the elemental damage on the hit does the work.
  fire: { dmg: "m_fire", mat: "SurtlingCore", hit: `(${addSE("SEMan.s_statusEffectBurning")} as SE_Burning)?.AddFireDamage(POWER);` },
  storm: { dmg: "m_lightning", mat: "Thunderstone", hit: `var bolt = ZNetScene.instance.GetPrefab("lightningAOE");\\nif (bolt) Object.Instantiate(bolt, TARGET.transform.position, Quaternion.identity);` },
  blink: { mat: "GreydwarfEye", player: true, self: `SOURCE.TeleportTo(SOURCE.transform.position + SOURCE.transform.forward * RADIUS, SOURCE.transform.rotation, distantTeleport: false);` },
  heal: { mat: "Bloodbag", self: `SOURCE.Heal(POWER * 0.5f, showText: true);` },
  poison: { dmg: "m_poison", mat: "Guck", hit: `(${addSE("SEMan.s_statusEffectPoison")} as SE_Poison)?.AddDamage(POWER);` },
  summon: { mat: "BoneFragments", self: `var echo = ZNetScene.instance.GetPrefab("Skeleton_Friendly");\\nif (echo) Object.Instantiate(echo, SOURCE.transform.position + SOURCE.transform.right * 2f, SOURCE.transform.rotation);` },
  flight: { mat: "Feathers", self: `${addSE(`"SlowFall".GetStableHashCode()`, "SOURCE")}; // the feather cape's effect` },
  void: { mat: "Ectoplasm", hit: `${addSE("SEMan.s_statusEffectSmoked")};\\n${addSE("SEMan.s_statusEffectWet")};` },
  lunar: {
    mat: "Crystal",
    hit: `if (EnvMan.IsNight())\\n{\\n    var moonlight = new HitData { m_point = TARGET.GetCenterPoint() };\\n    moonlight.m_damage.m_spirit = POWER * 0.5f;\\n    moonlight.SetAttacker(SOURCE);\\n    TARGET.Damage(moonlight);\\n}`,
  },
  // auto also ships its own Smelter / Fermenter patch (see productionPatch).
  auto: { mat: "Bronze", player: true, self: `SOURCE.m_autoPickupRange = Mathf.Max(SOURCE.m_autoPickupRange, RADIUS); // vanilla is 2 m` },
  neon: { mat: "Crystal", player: true, self: `SOURCE.Message(MessageHud.MessageType.TopLeft, "<color=#ff4fd8>LABEL</color>");` },
};

'''
s=s[:old_start]+new+s[old_end:]
open(p,'w').write(s)
EOF
