cd /tank/dev-worktrees/cyrus-v6-game-valheim && python3 - <<'EOF'
p='lib/cyrus/engine/games/valheim.ts'
s=open(p).read()
start=s.index('  const files = [pluginFile(c, a, settings), a.main, csproj(c, a), ...a.extra, manifest(c, a)];')
end=s.index('function l10nFile(c: Ctx, a: ArchOut): ModFile {')
new=r'''  // Where it must be installed decides whether Jötunn enforces matching versions between server and players.
  const side: ValheimSide = valheimModSide(k, { automation: has(c, "auto") });
  if (side === "both") a.jotunn = true;
  const keyed = settings.some((s) => s.type === "key");

  const files = [pluginFile(c, a, settings, side, keyed), a.main, csproj(c, a), ...a.extra, manifest(c, a), cyrusManifest(c, a, side)];
  if (input.model === "yakko") files.push(testProject(c));
  return { files, config: file(`config/com.cyrus.${snake}.cfg`, cfgFile(c, settings)), l10n: l10nFile(c, a), test: testFile(c, a) };
}

function pluginFile(c: Ctx, a: ArchOut, settings: Setting[], side: ValheimSide, keyed: boolean): ModFile {
  const { input, cls, P, B } = c;
  const vNote = input.version > 1 ? `// v${input.version}: retuned the numbers and moved every one of them into the BepInEx config.` : "";
  const { major, minor } = VALHEIM_TARGET.line;
  return file(
    `src/${P}.cs`,
    code`
      #if !CYRUS_TESTS
      ${a.usings ?? ""}
      ${keyed ? "using System.Linq;" : ""}
      using BepInEx;
      using BepInEx.Configuration;
      using BepInEx.Logging;
      using HarmonyLib;
      ${a.jotunn ? ["using Jotunn.Managers;", "using Jotunn.Utils;"] : ""}
      using UnityEngine;
      #endif

      namespace ${cls}
      {
      #if !CYRUS_TESTS
          /// <summary>${input.modName}: ${input.category.label.toLowerCase()} for Valheim ${major}.${minor}.x. Forged by Cyrus (${MODEL_NAME[input.model]}) v${input.version}.</summary>
          /// <remarks>${VALHEIM_SIDE_NOTE[side]}</remarks>
          ${vNote}
          [BepInPlugin(PluginGUID, PluginName, PluginVersion)]
          ${a.jotunn ? "[BepInDependency(Jotunn.Main.ModGuid)]" : ""}
          ${side === "both" ? "[NetworkCompatibility(CompatibilityLevel.EveryoneMustHaveMod, VersionStrictness.Minor)]" : ""}
          public class ${P} : BaseUnityPlugin
          {
              public const string PluginGUID = "com.cyrus.${c.snake}";
              public const string PluginName = "${input.modName}";
              public const string PluginVersion = "${input.version}.0.0";
              ${a.prefab ? `public const string PrefabName = "${a.prefab}";` : ""}

              internal static ManualLogSource Log;

              ${settings.map((s) => `public static ConfigEntry<${CS_TYPE[s.type]}> ${s.key};`)}

              private Harmony _harmony;

              private void Awake()
              {
                  Log = Logger;
                  // Iron Gate asks every mod to set this: the menu then shows the game is modded (and achievements are off).
                  Game.isModded = true;
                  WarnIfOutdated();
                  BindConfig();

                  _harmony = new Harmony(PluginGUID);
                  _harmony.PatchAll();
                  ${a.awake ?? ""}

                  Logger.LogInfo($"{PluginName} v{PluginVersion} loaded");
              }

              /// <summary>Built for one game line; a newer Valheim may have moved what the patches rely on.</summary>
              private void WarnIfOutdated()
              {
                  var game = global::Version.CurrentVersion;
                  if (game.m_major != ${major} || game.m_minor != ${minor})
                      Logger.LogWarning($"{PluginName} was built for Valheim ${major}.${minor}.x but this is {global::Version.GetVersionString()}. Check Cyrus for an update before reporting bugs.");
              }

              private void BindConfig()
              {
                  ${settings.map(bindLine)}
              }
              ${
                keyed
                  ? code`

                    /// <summary>Valheim reads keys through ZInput (Unity's Input System); KeyboardShortcut.IsDown() uses the legacy Input class.</summary>
                    internal static bool Pressed(KeyboardShortcut shortcut) =>
                        ZInput.GetKeyDown(shortcut.MainKey, false) && shortcut.Modifiers.All(key => ZInput.GetKey(key, false));`
                  : ""
              }

              private void OnDestroy() => _harmony?.UnpatchSelf();
          }
      #endif

          /// <summary>Pure balance math with no Unity types, so it can be unit tested outside the game.</summary>
          public static class ${B}
          {
              ${a.balance}

              public static float Clamp(float value, float min, float max) => value < min ? min : value > max ? max : value;

              public static int Clamp(int value, int min, int max) => value < min ? min : value > max ? max : value;
          }
      }`,
  );
}

const JOTUNN_NUGET = "JotunnLib";

function csproj(c: Ctx, a: ArchOut): ModFile {
  const ref = (name: string, dir = "$(ManagedPath)", extra = "") => `<Reference Include="${name}" HintPath="${dir}/${name}.dll" Private="false"${extra} />`;
  const managed = ["assembly_utils", "UnityEngine", "UnityEngine.CoreModule", ...(a.refs ?? [])];
  return file(
    `${c.cls}.csproj`,
    code`
      <Project Sdk="Microsoft.NET.Sdk">

        <!-- Built for Valheim ${VALHEIM_TARGET.line.major}.${VALHEIM_TARGET.line.minor}.x (network version ${VALHEIM_TARGET.networkVersion}), BepInExPack ${VALHEIM_TARGET.bepinexPack}${a.jotunn ? `, Jötunn ${VALHEIM_TARGET.jotunn}` : ""}.
             Point VALHEIM_INSTALL at your own Valheim (or Valheim dedicated server) folder with BepInEx installed:
             dotnet build -c Release -p:VALHEIM_INSTALL="/path/to/Valheim". Game files are referenced, never copied. -->
        <PropertyGroup>
          <TargetFramework>net48</TargetFramework>
          <AssemblyName>${c.cls}</AssemblyName>
          <RootNamespace>${c.cls}</RootNamespace>
          <Version>${c.input.version}.0.0</Version>
          <LangVersion>latest</LangVersion>
          <Nullable>disable</Nullable>
          <VALHEIM_INSTALL Condition="'$(VALHEIM_INSTALL)' == ''">C:/Program Files (x86)/Steam/steamapps/common/Valheim</VALHEIM_INSTALL>
          <ManagedPath Condition="'$(ManagedPath)' == '' And Exists('$(VALHEIM_INSTALL)/valheim_Data/Managed')">$(VALHEIM_INSTALL)/valheim_Data/Managed</ManagedPath>
          <ManagedPath Condition="'$(ManagedPath)' == ''">$(VALHEIM_INSTALL)/valheim_server_Data/Managed</ManagedPath>
          <BepInExPath Condition="'$(BepInExPath)' == ''">$(VALHEIM_INSTALL)/BepInEx</BepInExPath>
        </PropertyGroup>

        <ItemGroup>
          <!-- Thunderstore asks AI-assisted mods to say so. -->
          <AssemblyMetadata Include="AI_Assisted_Creation" Value="This assembly was created with the assistance of generative AI (Nxeon Cyrus)." />
          <AssemblyMetadata Include="AI_Model_Vendor" Value="Nxeon Cyrus (${MODEL_NAME[c.input.model]})" />
        </ItemGroup>

        <ItemGroup>
          <Compile Remove="tests/**" />
          ${a.jotunn ? `<Translations Include="Translations/**/*.json" />` : ""}
        </ItemGroup>

        <ItemGroup>
          <!-- Compile-time only: lets the code name private game members (Player.Update, m_nview...). Nothing is publicized at runtime. -->
          <PackageReference Include="BepInEx.AssemblyPublicizer.MSBuild" Version="${VALHEIM_TARGET.publicizer}" PrivateAssets="all" />
          <PackageReference Include="Microsoft.NETFramework.ReferenceAssemblies" Version="1.0.3" PrivateAssets="all" />
          ${a.jotunn ? `<PackageReference Include="${JOTUNN_NUGET}" Version="${VALHEIM_TARGET.jotunn}" />` : ""}
        </ItemGroup>

        <ItemGroup>
          ${ref("BepInEx", "$(BepInExPath)/core")}
          ${ref("0Harmony", "$(BepInExPath)/core")}
          ${ref("assembly_valheim", "$(ManagedPath)", ` Publicize="true"`)}
          ${managed.map((m) => ref(m))}
        </ItemGroup>

        <Target Name="DeployToBepInEx" AfterTargets="Build" Condition="'$(SkipDeploy)' != 'true' And Exists('$(BepInExPath)/plugins')">
          <Copy SourceFiles="$(TargetPath)" DestinationFolder="$(BepInExPath)/plugins/$(AssemblyName)" />
          ${a.jotunn ? `<Copy SourceFiles="@(Translations)" DestinationFolder="$(BepInExPath)/plugins/$(AssemblyName)/Translations/%(RecursiveDir)" />` : ""}
        </Target>

      </Project>`,
  );
}

/** Thunderstore's manifest.json, exactly its documented fields (name: [A-Za-z0-9_], description ≤ 250 chars). */
function manifest(c: Ctx, a: ArchOut): ModFile {
  return file(
    "manifest.json",
    JSON.stringify(
