/**
 * Static validator for Cyrus-generated Valheim mods (PURE, no I/O). Runs before a customer sees a build:
 *   1. dangerous APIs (valheim.ts VALHEIM_DANGEROUS_APIS) over C# with comments stripped, plus the csproj;
 *   2. build-script safety (no <Exec>, inline tasks or remote imports in any .csproj);
 *   3. structure: one BepInPlugin, GUID/version consistency, Thunderstore manifest rules, cyrus.json,
 *      Jötunn dependency wiring, version enforcement for content mods, Game.isModded, safe paths;
 *   4. file access only inside the mod's own folder or BepInEx/config;
 *   5. the knowledge pack's failure rules (known 1.0 breakages).
 * `ok` is false when anything has severity "block".
 */
import { VALHEIM_DANGEROUS_APIS, VALHEIM_TARGET, type ValheimSide } from "./valheim";
import { VALHEIM_KNOWLEDGE } from "./valheim.knowledge";

export type ValheimIssue = { severity: "block" | "warn"; code: string; message: string; file?: string; line?: number };
export type ValheimReport = {
  ok: boolean;
  /** Install side declared in cyrus.json, else inferred from the code. */
  side: ValheimSide | null;
  plugin: { guid: string; name: string; version: string } | null;
  issues: ValheimIssue[];
};
export type ValheimFile = { path: string; content: string };
export type ValidateOptions = {
  /** Validating a package for install/publish: missing manifest, README or cyrus.json become blocks instead of warnings. */
  forPackage?: boolean;
};

/** Removes // and /* *\/ comments but keeps string and char literals (so "file:///x" survives). */
export function stripCsComments(src: string): string {
  let out = "";
  let i = 0;
  const n = src.length;
  while (i < n) {
    const c = src[i];
    const d = src[i + 1];
    if (c === "/" && d === "/") {
      while (i < n && src[i] !== "\n") i++;
      continue;
    }
    if (c === "/" && d === "*") {
      i += 2;
      while (i < n && !(src[i] === "*" && src[i + 1] === "/")) {
        if (src[i] === "\n") out += "\n";
        i++;
      }
      i += 2;
      continue;
    }
    // verbatim strings: @"..." or $@"..." / @$"..." ("" escapes a quote)
    const verb = c === "@" && d === '"' ? 2 : (c === "$" && d === "@") || (c === "@" && d === "$") ? (src[i + 2] === '"' ? 3 : 0) : 0;
    if (verb) {
      out += src.slice(i, i + verb);
      i += verb;
      while (i < n) {
        if (src[i] === '"' && src[i + 1] === '"') {
          out += '""';
          i += 2;
          continue;
        }
        out += src[i];
        if (src[i++] === '"') break;
      }
      continue;
    }
    if (c === '"' || c === "'") {
      out += c;
      i++;
      while (i < n && src[i] !== c && src[i] !== "\n") {
        if (src[i] === "\\") {
          out += src[i] + (src[i + 1] ?? "");
          i += 2;
          continue;
        }
        out += src[i++];
      }
      if (i < n) out += src[i++];
      continue;
    }
    out += c;
    i++;
  }
  return out;
}

const lineOf = (text: string, index: number) => text.slice(0, index).split("\n").length;

const ALLOWED_TOP = new Set(["src", "tests", "config", "Translations", "music", "assets", "icons"]);
const ALLOWED_ROOT = /^(manifest\.json|cyrus\.json|README\.md|CHANGELOG\.md|LICENSE(\.md|\.txt)?|icon\.png|[A-Za-z0-9_.]+\.csproj)$/;
const BINARY = /\.(dll|exe|so|dylib|pdb|mdb|bat|cmd|ps1|sh|vbs|msi|jar)$/i;
const ALLOWED_PACKAGES = new Set(["bepinex.assemblypublicizer.msbuild", "jotunnlib", "microsoft.netframework.referenceassemblies", "xunit", "xunit.runner.visualstudio", "microsoft.net.test.sdk"]);
const CONTENT = /\bm_namedPrefabs\b|\bItemManager\.Instance\.AddItem\b|\bZoneManager\.Instance\.CreateClonedLocation\b|\bm_items\.Add\(|\bm_prefabs\.Add\(|\bPieceManager\.Instance\.AddPiece\b/;
const CLIENT_ONLY = /\bHud\b|\bMinimap\b|\bMusicMan\b|\bCameraEffects\b|\bPostProcessingBehaviour\b|\bEnvColorGrade|\bm_ambColorDay\b/;

function checkPaths(files: ValheimFile[], issues: ValheimIssue[]) {
  for (const f of files) {
    const p = f.path;
    if (!p || p.startsWith("/") || /^[A-Za-z]:/.test(p) || p.includes("\\") || p.split("/").some((s) => s === ".." || s === "." || s === "")) {
      issues.push({ severity: "block", code: "unsafe-path", file: p, message: `Unsafe file path "${p}": paths must be relative, forward-slash and stay inside the project.` });
      continue;
    }
    if (BINARY.test(p)) issues.push({ severity: "block", code: "binary-file", file: p, message: `"${p}" is an executable or prebuilt binary. Cyrus ships source only and never game or loader DLLs.` });
    const top = p.split("/")[0];
    if (!p.includes("/") ? !ALLOWED_ROOT.test(p) : !ALLOWED_TOP.has(top)) {
      issues.push({ severity: "warn", code: "unexpected-file", file: p, message: `"${p}" is outside the usual Valheim project layout (src/, tests/, config/, Translations/, music/).` });
    }
  }
}

function checkCsproj(f: ValheimFile, issues: ValheimIssue[]) {
  const x = f.content.replace(/<!--[\s\S]*?-->/g, "");
  if (/<Exec\b|<UsingTask\b|TaskFactory|<Import\s+Project\s*=\s*"(?:https?:|\\\\|\/\/)/i.test(x)) {
    issues.push({ severity: "block", code: "build-script", file: f.path, message: "The project file runs commands or loads tasks at build time. Cyrus only builds plain C# projects." });
  }
  for (const m of x.matchAll(/<PackageReference\s+Include="([^"]+)"/g)) {
    if (!ALLOWED_PACKAGES.has(m[1].toLowerCase())) issues.push({ severity: "warn", code: "unknown-package", file: f.path, line: lineOf(x, m.index ?? 0), message: `NuGet package "${m[1]}" is not on the Valheim allow-list; review its licence and what it does.` });
  }
  if (!f.path.startsWith("tests/")) {
    const tf = /<TargetFramework>([^<]+)<\/TargetFramework>/.exec(x)?.[1] ?? "";
    if (!/^(net4[6-8]\d?|netstandard2\.[01])$/.test(tf)) issues.push({ severity: "block", code: "target-framework", file: f.path, message: `TargetFramework "${tf || "missing"}" cannot load in Valheim's Mono runtime; use net48 (or netstandard2.1).` });
    if (/assembly_valheim\.dll[^>]*>/.test(x) && !/Private="false"|<Private>\s*false/i.test(x)) issues.push({ severity: "block", code: "copies-game-dll", file: f.path, message: "Game assemblies must be referenced with Private=\"false\" so they are never copied into the mod." });
  }
}

/** File reads/writes must stay inside the plugin's folder (Info.Location) or BepInEx's config folder. */
function checkFileAccess(f: ValheimFile, code: string, issues: ValheimIssue[]) {
  const io = /\b(?:File|Directory|Path)\.\w+\s*\(|\bUnityWebRequest\w*\.\w+\s*\(/g;
  if (!io.test(code)) return;
  const roots = /\bInfo\.Location\b|\bPaths\.(?:ConfigPath|PluginPath|BepInExConfigPath)\b|\bConfig\.ConfigFilePath\b/.test(code);
  if (!roots) issues.push({ severity: "warn", code: "file-root", file: f.path, message: "Reads or writes files without anchoring the path to the mod's folder (Info.Location) or BepInEx's config folder." });
  for (const m of code.matchAll(/"(?:[A-Za-z]:[\\/]|\/(?:home|etc|usr|var|root|Users|tmp)\b|~\/|%[A-Z]+%)[^"]*"/g)) {
    issues.push({ severity: "block", code: "absolute-path", file: f.path, line: lineOf(code, m.index ?? 0), message: `Absolute path ${m[0]} reaches outside the mod's own folder.` });
  }
  for (const m of code.matchAll(/"[^"\n]*\.\.[\\/][^"\n]*"|Environment\.GetFolderPath|Environment\.SpecialFolder|Application\.persistentDataPath/g)) {
    issues.push({ severity: "block", code: "escapes-folder", file: f.path, line: lineOf(code, m.index ?? 0), message: `"${m[0]}" climbs out of the mod's folder (or into the player's saves).` });
  }
}

function parseJson(f: ValheimFile | undefined, issues: ValheimIssue[]): Record<string, unknown> | null {
  if (!f) return null;
  try {
    const v = JSON.parse(f.content);
    return v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : null;
  } catch {
    issues.push({ severity: "block", code: "bad-json", file: f.path, message: `${f.path} is not valid JSON.` });
    return null;
  }
}

export function validateValheimMod(files: ValheimFile[], opts: ValidateOptions = {}): ValheimReport {
  const issues: ValheimIssue[] = [];
  const missing = opts.forPackage ? "block" : "warn";
  checkPaths(files, issues);

  const cs = files.filter((f) => f.path.endsWith(".cs"));
  const projects = files.filter((f) => f.path.endsWith(".csproj"));
  const stripped = new Map(cs.map((f) => [f.path, stripCsComments(f.content)]));
  const all = [...stripped.values()].join("\n");

  // 1 + 5: dangerous APIs and known failure rules, line-accurate.
  for (const f of [...cs, ...projects]) {
    const text = f.path.endsWith(".cs") ? stripped.get(f.path)! : f.content.replace(/<!--[\s\S]*?-->/g, "");
    for (const api of VALHEIM_DANGEROUS_APIS) {
      const m = new RegExp(api.pattern, "m").exec(text);
      if (m) issues.push({ severity: api.severity, code: "dangerous-api", file: f.path, line: lineOf(text, m.index), message: `${m[0].trim()}: ${api.why}` });
    }
