    if (!/:\s*BaseUnityPlugin\b/.test(src)) issues.push({ severity: "block", code: "base-class", file: pluginFiles[0].path, message: "The [BepInPlugin] class must derive from BaseUnityPlugin." });
    if (!/Version\.CurrentVersion/.test(src)) issues.push({ severity: "warn", code: "no-version-check", file: pluginFiles[0].path, message: "The plugin never checks which Valheim build it runs on, so an outdated mod fails silently." });
  }
