  const manifestFile = files.find((f) => f.path === "manifest.json");
  const manifest = parseJson(manifestFile, issues);
  if (!manifestFile) issues.push({ severity: missing, code: "no-manifest", message: "No manifest.json: mod managers and Thunderstore need one." });
  else if (manifest) {
    const name = String(manifest.name ?? "");
    const ver = String(manifest.version_number ?? "");
    const desc = String(manifest.description ?? "");
    const deps = Array.isArray(manifest.dependencies) ? manifest.dependencies.map(String) : null;
    if (!/^[A-Za-z0-9_]{1,128}$/.test(name)) issues.push({ severity: "block", code: "manifest-name", file: "manifest.json", message: `manifest name "${name}" may only use A-Z, a-z, 0-9 and _ (max 128).` });
    if (!/^\d+\.\d+\.\d+$/.test(ver)) issues.push({ severity: "block", code: "manifest-version", file: "manifest.json", message: `version_number "${ver}" must be Major.Minor.Patch.` });
