    if (typeof manifest.website_url !== "string") issues.push({ severity: "block", code: "manifest-website", file: "manifest.json", message: "website_url is required (use an empty string)." });
    if (!deps) issues.push({ severity: "block", code: "manifest-deps", file: "manifest.json", message: "dependencies must be an array." });
