      if (!pack) issues.push({ severity: "block", code: "manifest-bepinex", file: "manifest.json", message: "dependencies must include denikson-BepInExPack_Valheim." });
      else if (!pack.endsWith(`-${VALHEIM_TARGET.bepinexPack}`)) issues.push({ severity: "warn", code: "manifest-bepinex-version", file: "manifest.json", message: `BepInExPack pinned to ${pack.split("-").pop()}; Valheim ${VALHEIM_TARGET.line.major}.${VALHEIM_TARGET.line.minor} needs ${VALHEIM_TARGET.bepinexPack}.` });
