import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { CATEGORIES, CATEGORY_BY_KEY, GAME_BY_ID } from "../lib/cyrus/data";
import { buildModFiles } from "../lib/cyrus/engine/templates";
import valheim, { VALHEIM_DANGEROUS_APIS, VALHEIM_TARGET, valheimModSide } from "../lib/cyrus/games/valheim";
import { VALHEIM_KNOWLEDGE, apiLinesFor } from "../lib/cyrus/games/valheim.knowledge";
import { stripCsComments, validateValheimMod, type ValheimFile } from "../lib/cyrus/games/valheim.validate";
import type { CategoryKey, ModelId, ModFile } from "../lib/cyrus/types";

const UNIVERSAL = ["environment", "creatures", "weapons", "items", "magic", "vehicles", "gameplay", "quests", "minigames", "economy", "admin", "utility", "interface", "visuals", "audio", "performance"];

const game = GAME_BY_ID.valheim;
const gen = (category: CategoryKey, modName: string, prompt: string, model: ModelId = "yakko", version = 1) =>
