    /// <remarks>Install it on the server and on every player's PC (same version). Players without it are refused when they join.</remarks>
    [BepInPlugin(PluginGUID, PluginName, PluginVersion)]
    [BepInDependency(Jotunn.Main.ModGuid)]
    [NetworkCompatibility(CompatibilityLevel.EveryoneMustHaveMod, VersionStrictness.Minor)]
    public class StormDrakePlugin : BaseUnityPlugin
    {
        public const string PluginGUID = "com.cyrus.storm_drake";
        public const string PluginName = "Storm Drake";
        public const string PluginVersion = "1.0.0";
        public const string PrefabName = "StormDrake";

        internal static ManualLogSource Log;

        public static ConfigEntry<bool> Enabled;
        public static ConfigEntry<float> Health;
        public static ConfigEntry<float> SpeedBonus;
        public static ConfigEntry<float> ElementalDamage;
        public static ConfigEntry<float> Power;
        public static ConfigEntry<float> TamingTime;
        public static ConfigEntry<float> RideStamina;
        public static ConfigEntry<float> AbilityCooldown;
        public static ConfigEntry<float> SpawnChance;
        public static ConfigEntry<int> MaxSpawned;
        public static ConfigEntry<float> SpawnInterval;

        private Harmony _harmony;

        private void Awake()
        {
            Log = Logger;
            // Iron Gate asks every mod to set this: the menu then shows the game is modded (and achievements are off).
            Game.isModded = true;
            WarnIfOutdated();
            BindConfig();

            _harmony = new Harmony(PluginGUID);
            _harmony.PatchAll();

            Logger.LogInfo($"{PluginName} v{PluginVersion} loaded");
        }

        /// <summary>Built for one game line; a newer Valheim may have moved what the patches rely on.</summary>
        private void WarnIfOutdated()
        {
            var game = global::Version.CurrentVersion;
            if (game.m_major != 1 || game.m_minor != 0)
                Logger.LogWarning($"{PluginName} was built for Valheim 1.0.x but this is {(global::Version.GetVersionString())}. Check Cyrus for an update before reporting bugs.");
        }

        private void BindConfig()
        {
            Enabled = Config.Bind("General", "Enabled", true, "Master switch for everything this mod adds.");
            Health = Config.Bind("Creature", "Health", 250f, new ConfigDescription("Base health before star scaling.", new AcceptableValueRange<float>(10f, 10000f)));
            SpeedBonus = Config.Bind("Creature", "SpeedBonus", 0.4f, new ConfigDescription("Extra run speed as a fraction of the base creature.", new AcceptableValueRange<float>(0f, 2f)));
            ElementalDamage = Config.Bind("Effects", "ElementalDamage", 25.2f, new ConfigDescription("Elemental damage added to every attack.", new AcceptableValueRange<float>(0f, 300f)));
            Power = Config.Bind("Effects", "Power", 8.4f, new ConfigDescription("Strength of the creature's effects.", new AcceptableValueRange<float>(1f, 50f)));
            TamingTime = Config.Bind("Taming", "TamingTime", 1500f, new ConfigDescription("Seconds of feeding needed to tame.", new AcceptableValueRange<float>(30f, 7200f)));
            RideStamina = Config.Bind("Riding", "RideStamina", 200f, new ConfigDescription("Saddle stamina while ridden.", new AcceptableValueRange<float>(20f, 1000f)));
            AbilityCooldown = Config.Bind("Riding", "AbilityCooldown", 6.1f, new ConfigDescription("Seconds between rider buffs.", new AcceptableValueRange<float>(0.5f, 120f)));
            SpawnChance = Config.Bind("Spawning", "SpawnChance", 28f, new ConfigDescription("Percent chance per spawn check.", new AcceptableValueRange<float>(0f, 100f)));
            MaxSpawned = Config.Bind("Spawning", "MaxSpawned", 3, new ConfigDescription("Most alive at once per spawn area.", new AcceptableValueRange<int>(1, 10)));
            SpawnInterval = Config.Bind("Spawning", "SpawnInterval", 300f, new ConfigDescription("Seconds between spawn checks.", new AcceptableValueRange<float>(30f, 3600f)));
        }

        private void OnDestroy() => _harmony?.UnpatchSelf();
    }
