	public void UpdateAvailable(HashSet<string> knownRecipies, Player player, bool hideUnavailable, bool noPlacementCost)
	{
		m_enabledPieces.Clear();
		m_availablePieces.Clear();
		if (m_availablePiecesByCategory.Count == 0)
		{
			for (int i = 0; i < 9; i++)
			{
				m_availablePiecesByCategory.Add(new List<Piece>());
			}
		}
		else
		{
			foreach (List<Piece> item in m_availablePiecesByCategory)
			{
				item.Clear();
			}
		}
		foreach (GameObject piece in m_pieces)
		{
			Piece component = piece.GetComponent<Piece>();
			if (!noPlacementCost || component.m_canRockJade)
			{
				if (!component.m_enabled && (!(player.CurrentSeason != null) || !player.CurrentSeason.Pieces.Contains(piece)))
				{
					continue;
				}
				m_enabledPieces.Add(component);
				if (!knownRecipies.Contains(component.m_name) || (hideUnavailable && !player.HaveRequirements(component, Player.RequirementMode.CanAlmostBuild)))
				{
					continue;
				}
			}
			else
			{
				m_enabledPieces.Add(component);
			}
			m_availablePieces.Add(component);
			if (component.m_category == Piece.PieceCategory.All)
			{
				for (int j = 0; j < 9; j++)
				{
					m_availablePiecesByCategory[j].Add(component);
				}
			}
			else
			{
				m_availablePiecesByCategory[(int)component.m_category].Add(component);
			}
		}
	}

